-- Gerado por scripts/importar_lei.py. Pode ser executado mais de uma vez:
-- apaga e recria os dispositivos desta norma (as anotações dos usuários
-- ficam presas ao 'caminho' e são religadas no final).
begin;
insert into public.normas (slug, titulo, apelido, ementa, fonte_url) values ('lei-9605-1998', 'Lei nº 9.605, de 12 de fevereiro de 1998', 'Lei de Crimes Ambientais', 'Dispõe sobre as sanções penais e administrativas derivadas de condutas e atividades lesivas ao meio ambiente, e dá outras providências.', 'https://www.planalto.gov.br/ccivil_03/leis/l9605.htm')
  on conflict (slug) do update set titulo = excluded.titulo, apelido = excluded.apelido, ementa = excluded.ementa, fonte_url = excluded.fonte_url, atualizado_em = now();

create temp table _novos (like public.dispositivos including defaults) on commit drop;
insert into _novos (norma_id, caminho, caminho_pai, tipo, rotulo, artigo, texto, notas, estrutura, ordem) values
((select id from public.normas where slug = 'lei-9605-1998'), 'art1', null, 'artigo', 'Art. 1º', 'Art. 1º', '(VETADO)', '{}'::text[], 'CAPÍTULO I – DISPOSIÇÕES GERAIS', 1),
((select id from public.normas where slug = 'lei-9605-1998'), 'art2', null, 'artigo', 'Art. 2º', 'Art. 2º', 'Quem, de qualquer forma, concorre para a prática dos crimes previstos nesta Lei, incide nas penas a estes cominadas, na medida da sua culpabilidade, bem como o diretor, o administrador, o membro de conselho e de órgão técnico, o auditor, o gerente, o preposto ou mandatário de pessoa jurídica, que, sabendo da conduta criminosa de outrem, deixar de impedir a sua prática, quando podia agir para evitá-la.', '{}'::text[], 'CAPÍTULO I – DISPOSIÇÕES GERAIS', 2),
((select id from public.normas where slug = 'lei-9605-1998'), 'art3', null, 'artigo', 'Art. 3º', 'Art. 3º', 'As pessoas jurídicas serão responsabilizadas administrativa, civil e penalmente conforme o disposto nesta Lei, nos casos em que a infração seja cometida por decisão de seu representante legal ou contratual, ou de seu órgão colegiado, no interesse ou benefício da sua entidade.', '{}'::text[], 'CAPÍTULO I – DISPOSIÇÕES GERAIS', 3),
((select id from public.normas where slug = 'lei-9605-1998'), 'art3.pu', 'art3', 'paragrafo', 'Parágrafo único', 'Art. 3º', 'A responsabilidade das pessoas jurídicas não exclui a das pessoas físicas, autoras, co-autoras ou partícipes do mesmo fato.', '{}'::text[], 'CAPÍTULO I – DISPOSIÇÕES GERAIS', 4),
((select id from public.normas where slug = 'lei-9605-1998'), 'art4', null, 'artigo', 'Art. 4º', 'Art. 4º', 'Poderá ser desconsiderada a pessoa jurídica sempre que sua personalidade for obstáculo ao ressarcimento de prejuízos causados à qualidade do meio ambiente.', '{}'::text[], 'CAPÍTULO I – DISPOSIÇÕES GERAIS', 5),
((select id from public.normas where slug = 'lei-9605-1998'), 'art5', null, 'artigo', 'Art. 5º', 'Art. 5º', '(VETADO)', '{}'::text[], 'CAPÍTULO I – DISPOSIÇÕES GERAIS', 6),
((select id from public.normas where slug = 'lei-9605-1998'), 'art6', null, 'artigo', 'Art. 6º', 'Art. 6º', 'Para imposição e gradação da penalidade, a autoridade competente observará:', '{}'::text[], 'CAPÍTULO II – DA APLICAÇÃO DA PENA', 7),
((select id from public.normas where slug = 'lei-9605-1998'), 'art6.inc1', 'art6', 'inciso', 'I', 'Art. 6º', 'a gravidade do fato, tendo em vista os motivos da infração e suas conseqüências para a saúde pública e para o meio ambiente;', '{}'::text[], 'CAPÍTULO II – DA APLICAÇÃO DA PENA', 8),
((select id from public.normas where slug = 'lei-9605-1998'), 'art6.inc2', 'art6', 'inciso', 'II', 'Art. 6º', 'os antecedentes do infrator quanto ao cumprimento da legislação de interesse ambiental;', '{}'::text[], 'CAPÍTULO II – DA APLICAÇÃO DA PENA', 9),
((select id from public.normas where slug = 'lei-9605-1998'), 'art6.inc3', 'art6', 'inciso', 'III', 'Art. 6º', 'a situação econômica do infrator, no caso de multa.', '{}'::text[], 'CAPÍTULO II – DA APLICAÇÃO DA PENA', 10),
((select id from public.normas where slug = 'lei-9605-1998'), 'art7', null, 'artigo', 'Art. 7º', 'Art. 7º', 'As penas restritivas de direitos são autônomas e substituem as privativas de liberdade quando:', '{}'::text[], 'CAPÍTULO II – DA APLICAÇÃO DA PENA', 11),
((select id from public.normas where slug = 'lei-9605-1998'), 'art7.inc1', 'art7', 'inciso', 'I', 'Art. 7º', 'tratar-se de crime culposo ou for aplicada a pena privativa de liberdade inferior a quatro anos;', '{}'::text[], 'CAPÍTULO II – DA APLICAÇÃO DA PENA', 12),
((select id from public.normas where slug = 'lei-9605-1998'), 'art7.inc2', 'art7', 'inciso', 'II', 'Art. 7º', 'a culpabilidade, os antecedentes, a conduta social e a personalidade do condenado, bem como os motivos e as circunstâncias do crime indicarem que a substituição seja suficiente para efeitos de reprovação e prevenção do crime.', '{}'::text[], 'CAPÍTULO II – DA APLICAÇÃO DA PENA', 13),
((select id from public.normas where slug = 'lei-9605-1998'), 'art7.pu', 'art7', 'paragrafo', 'Parágrafo único', 'Art. 7º', 'As penas restritivas de direitos a que se refere este artigo terão a mesma duração da pena privativa de liberdade substituída.', '{}'::text[], 'CAPÍTULO II – DA APLICAÇÃO DA PENA', 14),
((select id from public.normas where slug = 'lei-9605-1998'), 'art8', null, 'artigo', 'Art. 8º', 'Art. 8º', 'As penas restritivas de direito são:', '{}'::text[], 'CAPÍTULO II – DA APLICAÇÃO DA PENA', 15),
((select id from public.normas where slug = 'lei-9605-1998'), 'art8.inc1', 'art8', 'inciso', 'I', 'Art. 8º', 'prestação de serviços à comunidade;', '{}'::text[], 'CAPÍTULO II – DA APLICAÇÃO DA PENA', 16),
((select id from public.normas where slug = 'lei-9605-1998'), 'art8.inc2', 'art8', 'inciso', 'II', 'Art. 8º', 'interdição temporária de direitos;', '{}'::text[], 'CAPÍTULO II – DA APLICAÇÃO DA PENA', 17),
((select id from public.normas where slug = 'lei-9605-1998'), 'art8.inc3', 'art8', 'inciso', 'III', 'Art. 8º', 'suspensão parcial ou total de atividades;', '{}'::text[], 'CAPÍTULO II – DA APLICAÇÃO DA PENA', 18),
((select id from public.normas where slug = 'lei-9605-1998'), 'art8.inc4', 'art8', 'inciso', 'IV', 'Art. 8º', 'prestação pecuniária;', '{}'::text[], 'CAPÍTULO II – DA APLICAÇÃO DA PENA', 19),
((select id from public.normas where slug = 'lei-9605-1998'), 'art8.inc5', 'art8', 'inciso', 'V', 'Art. 8º', 'recolhimento domiciliar.', '{}'::text[], 'CAPÍTULO II – DA APLICAÇÃO DA PENA', 20),
((select id from public.normas where slug = 'lei-9605-1998'), 'art9', null, 'artigo', 'Art. 9º', 'Art. 9º', 'A prestação de serviços à comunidade consiste na atribuição ao condenado de tarefas gratuitas junto a parques e jardins públicos e unidades de conservação, e, no caso de dano da coisa particular, pública ou tombada, na restauração desta, se possível.', '{}'::text[], 'CAPÍTULO II – DA APLICAÇÃO DA PENA', 21),
((select id from public.normas where slug = 'lei-9605-1998'), 'art10', null, 'artigo', 'Art. 10', 'Art. 10', 'As penas de interdição temporária de direito são a proibição de o condenado contratar com o Poder Público, de receber incentivos fiscais ou quaisquer outros benefícios, bem como de participar de licitações, pelo prazo de cinco anos, no caso de crimes dolosos, e de três anos, no de crimes culposos.', '{}'::text[], 'CAPÍTULO II – DA APLICAÇÃO DA PENA', 22),
((select id from public.normas where slug = 'lei-9605-1998'), 'art11', null, 'artigo', 'Art. 11', 'Art. 11', 'A suspensão de atividades será aplicada quando estas não estiverem obedecendo às prescrições legais.', '{}'::text[], 'CAPÍTULO II – DA APLICAÇÃO DA PENA', 23),
((select id from public.normas where slug = 'lei-9605-1998'), 'art12', null, 'artigo', 'Art. 12', 'Art. 12', 'A prestação pecuniária consiste no pagamento em dinheiro à vítima ou à entidade pública ou privada com fim social, de importância, fixada pelo juiz, não inferior a um salário mínimo nem superior a trezentos e sessenta salários mínimos. O valor pago será deduzido do montante de eventual reparação civil a que for condenado o infrator.', '{}'::text[], 'CAPÍTULO II – DA APLICAÇÃO DA PENA', 24),
((select id from public.normas where slug = 'lei-9605-1998'), 'art13', null, 'artigo', 'Art. 13', 'Art. 13', 'O recolhimento domiciliar baseia-se na autodisciplina e senso de responsabilidade do condenado, que deverá, sem vigilância, trabalhar, freqüentar curso ou exercer atividade autorizada, permanecendo recolhido nos dias e horários de folga em residência ou em qualquer local destinado a sua moradia habitual, conforme estabelecido na sentença condenatória.', '{}'::text[], 'CAPÍTULO II – DA APLICAÇÃO DA PENA', 25),
((select id from public.normas where slug = 'lei-9605-1998'), 'art14', null, 'artigo', 'Art. 14', 'Art. 14', 'São circunstâncias que atenuam a pena:', '{}'::text[], 'CAPÍTULO II – DA APLICAÇÃO DA PENA', 26),
((select id from public.normas where slug = 'lei-9605-1998'), 'art14.inc1', 'art14', 'inciso', 'I', 'Art. 14', 'baixo grau de instrução ou escolaridade do agente;', '{}'::text[], 'CAPÍTULO II – DA APLICAÇÃO DA PENA', 27),
((select id from public.normas where slug = 'lei-9605-1998'), 'art14.inc2', 'art14', 'inciso', 'II', 'Art. 14', 'arrependimento do infrator, manifestado pela espontânea reparação do dano, ou limitação significativa da degradação ambiental causada;', '{}'::text[], 'CAPÍTULO II – DA APLICAÇÃO DA PENA', 28),
((select id from public.normas where slug = 'lei-9605-1998'), 'art14.inc3', 'art14', 'inciso', 'III', 'Art. 14', 'comunicação prévia pelo agente do perigo iminente de degradação ambiental;', '{}'::text[], 'CAPÍTULO II – DA APLICAÇÃO DA PENA', 29),
((select id from public.normas where slug = 'lei-9605-1998'), 'art14.inc4', 'art14', 'inciso', 'IV', 'Art. 14', 'colaboração com os agentes encarregados da vigilância e do controle ambiental.', '{}'::text[], 'CAPÍTULO II – DA APLICAÇÃO DA PENA', 30),
((select id from public.normas where slug = 'lei-9605-1998'), 'art15', null, 'artigo', 'Art. 15', 'Art. 15', 'São circunstâncias que agravam a pena, quando não constituem ou qualificam o crime:', '{}'::text[], 'CAPÍTULO II – DA APLICAÇÃO DA PENA', 31),
((select id from public.normas where slug = 'lei-9605-1998'), 'art15.inc1', 'art15', 'inciso', 'I', 'Art. 15', 'reincidência nos crimes de natureza ambiental;', '{}'::text[], 'CAPÍTULO II – DA APLICAÇÃO DA PENA', 32),
((select id from public.normas where slug = 'lei-9605-1998'), 'art15.inc2', 'art15', 'inciso', 'II', 'Art. 15', 'ter o agente cometido a infração:', '{}'::text[], 'CAPÍTULO II – DA APLICAÇÃO DA PENA', 33),
((select id from public.normas where slug = 'lei-9605-1998'), 'art15.inc2.a', 'art15.inc2', 'alinea', 'a)', 'Art. 15', 'para obter vantagem pecuniária;', '{}'::text[], 'CAPÍTULO II – DA APLICAÇÃO DA PENA', 34),
((select id from public.normas where slug = 'lei-9605-1998'), 'art15.inc2.b', 'art15.inc2', 'alinea', 'b)', 'Art. 15', 'coagindo outrem para a execução material da infração;', '{}'::text[], 'CAPÍTULO II – DA APLICAÇÃO DA PENA', 35),
((select id from public.normas where slug = 'lei-9605-1998'), 'art15.inc2.c', 'art15.inc2', 'alinea', 'c)', 'Art. 15', 'afetando ou expondo a perigo, de maneira grave, a saúde pública ou o meio ambiente;', '{}'::text[], 'CAPÍTULO II – DA APLICAÇÃO DA PENA', 36),
((select id from public.normas where slug = 'lei-9605-1998'), 'art15.inc2.d', 'art15.inc2', 'alinea', 'd)', 'Art. 15', 'concorrendo para danos à propriedade alheia;', '{}'::text[], 'CAPÍTULO II – DA APLICAÇÃO DA PENA', 37),
((select id from public.normas where slug = 'lei-9605-1998'), 'art15.inc2.e', 'art15.inc2', 'alinea', 'e)', 'Art. 15', 'atingindo áreas de unidades de conservação ou áreas sujeitas, por ato do Poder Público, a regime especial de uso;', '{}'::text[], 'CAPÍTULO II – DA APLICAÇÃO DA PENA', 38),
((select id from public.normas where slug = 'lei-9605-1998'), 'art15.inc2.f', 'art15.inc2', 'alinea', 'f)', 'Art. 15', 'atingindo áreas urbanas ou quaisquer assentamentos humanos;', '{}'::text[], 'CAPÍTULO II – DA APLICAÇÃO DA PENA', 39),
((select id from public.normas where slug = 'lei-9605-1998'), 'art15.inc2.g', 'art15.inc2', 'alinea', 'g)', 'Art. 15', 'em período de defeso à fauna;', '{}'::text[], 'CAPÍTULO II – DA APLICAÇÃO DA PENA', 40),
((select id from public.normas where slug = 'lei-9605-1998'), 'art15.inc2.h', 'art15.inc2', 'alinea', 'h)', 'Art. 15', 'em domingos ou feriados;', '{}'::text[], 'CAPÍTULO II – DA APLICAÇÃO DA PENA', 41),
((select id from public.normas where slug = 'lei-9605-1998'), 'art15.inc2.i', 'art15.inc2', 'alinea', 'i)', 'Art. 15', 'à noite;', '{}'::text[], 'CAPÍTULO II – DA APLICAÇÃO DA PENA', 42),
((select id from public.normas where slug = 'lei-9605-1998'), 'art15.inc2.j', 'art15.inc2', 'alinea', 'j)', 'Art. 15', 'em épocas de seca ou inundações;', '{}'::text[], 'CAPÍTULO II – DA APLICAÇÃO DA PENA', 43),
((select id from public.normas where slug = 'lei-9605-1998'), 'art15.inc2.l', 'art15.inc2', 'alinea', 'l)', 'Art. 15', 'no interior do espaço territorial especialmente protegido;', '{}'::text[], 'CAPÍTULO II – DA APLICAÇÃO DA PENA', 44),
((select id from public.normas where slug = 'lei-9605-1998'), 'art15.inc2.m', 'art15.inc2', 'alinea', 'm)', 'Art. 15', 'com o emprego de métodos cruéis para abate ou captura de animais;', '{}'::text[], 'CAPÍTULO II – DA APLICAÇÃO DA PENA', 45),
((select id from public.normas where slug = 'lei-9605-1998'), 'art15.inc2.n', 'art15.inc2', 'alinea', 'n)', 'Art. 15', 'mediante fraude ou abuso de confiança;', '{}'::text[], 'CAPÍTULO II – DA APLICAÇÃO DA PENA', 46),
((select id from public.normas where slug = 'lei-9605-1998'), 'art15.inc2.o', 'art15.inc2', 'alinea', 'o)', 'Art. 15', 'mediante abuso do direito de licença, permissão ou autorização ambiental;', '{}'::text[], 'CAPÍTULO II – DA APLICAÇÃO DA PENA', 47),
((select id from public.normas where slug = 'lei-9605-1998'), 'art15.inc2.p', 'art15.inc2', 'alinea', 'p)', 'Art. 15', 'no interesse de pessoa jurídica mantida, total ou parcialmente, por verbas públicas ou beneficiada por incentivos fiscais;', '{}'::text[], 'CAPÍTULO II – DA APLICAÇÃO DA PENA', 48),
((select id from public.normas where slug = 'lei-9605-1998'), 'art15.inc2.q', 'art15.inc2', 'alinea', 'q)', 'Art. 15', 'atingindo espécies ameaçadas, listadas em relatórios oficiais das autoridades competentes;', '{}'::text[], 'CAPÍTULO II – DA APLICAÇÃO DA PENA', 49),
((select id from public.normas where slug = 'lei-9605-1998'), 'art15.inc2.r', 'art15.inc2', 'alinea', 'r)', 'Art. 15', 'facilitada por funcionário público no exercício de suas funções.', '{}'::text[], 'CAPÍTULO II – DA APLICAÇÃO DA PENA', 50),
((select id from public.normas where slug = 'lei-9605-1998'), 'art16', null, 'artigo', 'Art. 16', 'Art. 16', 'Nos crimes previstos nesta Lei, a suspensão condicional da pena pode ser aplicada nos casos de condenação a pena privativa de liberdade não superior a três anos.', '{}'::text[], 'CAPÍTULO II – DA APLICAÇÃO DA PENA', 51),
((select id from public.normas where slug = 'lei-9605-1998'), 'art17', null, 'artigo', 'Art. 17', 'Art. 17', 'A verificação da reparação a que se refere o § 2º do art. 78 do Código Penal será feita mediante laudo de reparação do dano ambiental, e as condições a serem impostas pelo juiz deverão relacionar-se com a proteção ao meio ambiente.', '{}'::text[], 'CAPÍTULO II – DA APLICAÇÃO DA PENA', 52),
((select id from public.normas where slug = 'lei-9605-1998'), 'art18', null, 'artigo', 'Art. 18', 'Art. 18', 'A multa será calculada segundo os critérios do Código Penal; se revelar-se ineficaz, ainda que aplicada no valor máximo, poderá ser aumentada até três vezes, tendo em vista o valor da vantagem econômica auferida.', '{}'::text[], 'CAPÍTULO II – DA APLICAÇÃO DA PENA', 53),
((select id from public.normas where slug = 'lei-9605-1998'), 'art19', null, 'artigo', 'Art. 19', 'Art. 19', 'A perícia de constatação do dano ambiental, sempre que possível, fixará o montante do prejuízo causado para efeitos de prestação de fiança e cálculo de multa.', '{}'::text[], 'CAPÍTULO II – DA APLICAÇÃO DA PENA', 54),
((select id from public.normas where slug = 'lei-9605-1998'), 'art19.pu', 'art19', 'paragrafo', 'Parágrafo único', 'Art. 19', 'A perícia produzida no inquérito civil ou no juízo cível poderá ser aproveitada no processo penal, instaurando-se o contraditório.', '{}'::text[], 'CAPÍTULO II – DA APLICAÇÃO DA PENA', 55),
((select id from public.normas where slug = 'lei-9605-1998'), 'art20', null, 'artigo', 'Art. 20', 'Art. 20', 'A sentença penal condenatória, sempre que possível, fixará o valor mínimo para reparação dos danos causados pela infração, considerando os prejuízos sofridos pelo ofendido ou pelo meio ambiente.', '{}'::text[], 'CAPÍTULO II – DA APLICAÇÃO DA PENA', 56),
((select id from public.normas where slug = 'lei-9605-1998'), 'art20.pu', 'art20', 'paragrafo', 'Parágrafo único', 'Art. 20', 'Transitada em julgado a sentença condenatória, a execução poderá efetuar-se pelo valor fixado nos termos do caput, sem prejuízo da liquidação para apuração do dano efetivamente sofrido.', '{}'::text[], 'CAPÍTULO II – DA APLICAÇÃO DA PENA', 57),
((select id from public.normas where slug = 'lei-9605-1998'), 'art21', null, 'artigo', 'Art. 21', 'Art. 21', 'As penas aplicáveis isolada, cumulativa ou alternativamente às pessoas jurídicas, de acordo com o disposto no art. 3º, são:', '{}'::text[], 'CAPÍTULO II – DA APLICAÇÃO DA PENA', 58),
((select id from public.normas where slug = 'lei-9605-1998'), 'art21.inc1', 'art21', 'inciso', 'I', 'Art. 21', 'multa;', '{}'::text[], 'CAPÍTULO II – DA APLICAÇÃO DA PENA', 59),
((select id from public.normas where slug = 'lei-9605-1998'), 'art21.inc2', 'art21', 'inciso', 'II', 'Art. 21', 'restritivas de direitos;', '{}'::text[], 'CAPÍTULO II – DA APLICAÇÃO DA PENA', 60),
((select id from public.normas where slug = 'lei-9605-1998'), 'art21.inc3', 'art21', 'inciso', 'III', 'Art. 21', 'prestação de serviços à comunidade.', '{}'::text[], 'CAPÍTULO II – DA APLICAÇÃO DA PENA', 61),
((select id from public.normas where slug = 'lei-9605-1998'), 'art22', null, 'artigo', 'Art. 22', 'Art. 22', 'As penas restritivas de direitos da pessoa jurídica são:', '{}'::text[], 'CAPÍTULO II – DA APLICAÇÃO DA PENA', 62),
((select id from public.normas where slug = 'lei-9605-1998'), 'art22.inc1', 'art22', 'inciso', 'I', 'Art. 22', 'suspensão parcial ou total de atividades;', '{}'::text[], 'CAPÍTULO II – DA APLICAÇÃO DA PENA', 63),
((select id from public.normas where slug = 'lei-9605-1998'), 'art22.inc2', 'art22', 'inciso', 'II', 'Art. 22', 'interdição temporária de estabelecimento, obra ou atividade;', '{}'::text[], 'CAPÍTULO II – DA APLICAÇÃO DA PENA', 64),
((select id from public.normas where slug = 'lei-9605-1998'), 'art22.inc3', 'art22', 'inciso', 'III', 'Art. 22', 'proibição de contratar com o Poder Público, bem como dele obter subsídios, subvenções ou doações.', '{}'::text[], 'CAPÍTULO II – DA APLICAÇÃO DA PENA', 65),
((select id from public.normas where slug = 'lei-9605-1998'), 'art22.p1', 'art22', 'paragrafo', '§ 1º', 'Art. 22', 'A suspensão de atividades será aplicada quando estas não estiverem obedecendo às disposições legais ou regulamentares, relativas à proteção do meio ambiente.', '{}'::text[], 'CAPÍTULO II – DA APLICAÇÃO DA PENA', 66),
((select id from public.normas where slug = 'lei-9605-1998'), 'art22.p2', 'art22', 'paragrafo', '§ 2º', 'Art. 22', 'A interdição será aplicada quando o estabelecimento, obra ou atividade estiver funcionando sem a devida autorização, ou em desacordo com a concedida, ou com violação de disposição legal ou regulamentar.', '{}'::text[], 'CAPÍTULO II – DA APLICAÇÃO DA PENA', 67),
((select id from public.normas where slug = 'lei-9605-1998'), 'art22.p3', 'art22', 'paragrafo', '§ 3º', 'Art. 22', 'A proibição de contratar com o Poder Público e dele obter subsídios, subvenções ou doações não poderá exceder o prazo de dez anos.', '{}'::text[], 'CAPÍTULO II – DA APLICAÇÃO DA PENA', 68),
((select id from public.normas where slug = 'lei-9605-1998'), 'art23', null, 'artigo', 'Art. 23', 'Art. 23', 'A prestação de serviços à comunidade pela pessoa jurídica consistirá em:', '{}'::text[], 'CAPÍTULO II – DA APLICAÇÃO DA PENA', 69),
((select id from public.normas where slug = 'lei-9605-1998'), 'art23.inc1', 'art23', 'inciso', 'I', 'Art. 23', 'custeio de programas e de projetos ambientais;', '{}'::text[], 'CAPÍTULO II – DA APLICAÇÃO DA PENA', 70),
((select id from public.normas where slug = 'lei-9605-1998'), 'art23.inc2', 'art23', 'inciso', 'II', 'Art. 23', 'execução de obras de recuperação de áreas degradadas;', '{}'::text[], 'CAPÍTULO II – DA APLICAÇÃO DA PENA', 71),
((select id from public.normas where slug = 'lei-9605-1998'), 'art23.inc3', 'art23', 'inciso', 'III', 'Art. 23', 'manutenção de espaços públicos;', '{}'::text[], 'CAPÍTULO II – DA APLICAÇÃO DA PENA', 72),
((select id from public.normas where slug = 'lei-9605-1998'), 'art23.inc4', 'art23', 'inciso', 'IV', 'Art. 23', 'contribuições a entidades ambientais ou culturais públicas.', '{}'::text[], 'CAPÍTULO II – DA APLICAÇÃO DA PENA', 73),
((select id from public.normas where slug = 'lei-9605-1998'), 'art24', null, 'artigo', 'Art. 24', 'Art. 24', 'A pessoa jurídica constituída ou utilizada, preponderantemente, com o fim de permitir, facilitar ou ocultar a prática de crime definido nesta Lei terá decretada sua liquidação forçada, seu patrimônio será considerado instrumento do crime e como tal perdido em favor do Fundo Penitenciário Nacional.', '{}'::text[], 'CAPÍTULO II – DA APLICAÇÃO DA PENA', 74),
((select id from public.normas where slug = 'lei-9605-1998'), 'art25', null, 'artigo', 'Art. 25', 'Art. 25', 'Verificada a infração, serão apreendidos seus produtos e instrumentos, lavrando-se os respectivos autos.', array['Vide ADPF 640']::text[], 'CAPÍTULO III – DA APREENSÃO DO PRODUTO E DO INSTRUMENTO DE INFRAÇÃO ADMINISTRATIVA OU DE CRIME', 75),
((select id from public.normas where slug = 'lei-9605-1998'), 'art25.p1', 'art25', 'paragrafo', '§ 1º', 'Art. 25', 'Os animais serão prioritariamente libertados em seu habitat ou, sendo tal medida inviável ou não recomendável por questões sanitárias, entregues a jardins zoológicos, fundações ou entidades assemelhadas, para guarda e cuidados sob a responsabilidade de técnicos habilitados.', array['Redação dada pela Lei nº 13.052, de 2014']::text[], 'CAPÍTULO III – DA APREENSÃO DO PRODUTO E DO INSTRUMENTO DE INFRAÇÃO ADMINISTRATIVA OU DE CRIME', 76),
((select id from public.normas where slug = 'lei-9605-1998'), 'art25.p2', 'art25', 'paragrafo', '§ 2º', 'Art. 25', 'Até que os animais sejam entregues às instituições mencionadas no § 1º deste artigo, o órgão autuante zelará para que eles sejam mantidos em condições adequadas de acondicionamento e transporte que garantam o seu bem-estar físico.', array['Redação dada pela Lei nº 13.052, de 2014','Vide ADPF 640']::text[], 'CAPÍTULO III – DA APREENSÃO DO PRODUTO E DO INSTRUMENTO DE INFRAÇÃO ADMINISTRATIVA OU DE CRIME', 77),
((select id from public.normas where slug = 'lei-9605-1998'), 'art25.p3', 'art25', 'paragrafo', '§ 3º', 'Art. 25', 'Tratando-se de produtos perecíveis ou madeiras, serão estes avaliados e doados a instituições científicas, hospitalares, penais e outras com fins beneficentes. (Renumerando do §2º para §3º pela Lei nº 13.052, de 2014)', '{}'::text[], 'CAPÍTULO III – DA APREENSÃO DO PRODUTO E DO INSTRUMENTO DE INFRAÇÃO ADMINISTRATIVA OU DE CRIME', 78),
((select id from public.normas where slug = 'lei-9605-1998'), 'art25.p4', 'art25', 'paragrafo', '§ 4º', 'Art. 25', 'Os produtos e subprodutos da fauna não perecíveis serão destruídos ou doados a instituições científicas, culturais ou educacionais. (Renumerando do §3º para §4º pela Lei nº 13.052, de 2014)', '{}'::text[], 'CAPÍTULO III – DA APREENSÃO DO PRODUTO E DO INSTRUMENTO DE INFRAÇÃO ADMINISTRATIVA OU DE CRIME', 79),
((select id from public.normas where slug = 'lei-9605-1998'), 'art25.p5', 'art25', 'paragrafo', '§ 5º', 'Art. 25', 'Os instrumentos utilizados na prática da infração serão vendidos, garantida a sua descaracterização por meio da reciclagem. (Renumerando do §4º para §5º pela Lei nº 13.052, de 2014)', '{}'::text[], 'CAPÍTULO III – DA APREENSÃO DO PRODUTO E DO INSTRUMENTO DE INFRAÇÃO ADMINISTRATIVA OU DE CRIME', 80),
((select id from public.normas where slug = 'lei-9605-1998'), 'art26', null, 'artigo', 'Art. 26', 'Art. 26', 'Nas infrações penais previstas nesta Lei, a ação penal é pública incondicionada.', '{}'::text[], 'CAPÍTULO IV – DA AÇÃO E DO PROCESSO PENAL', 81),
((select id from public.normas where slug = 'lei-9605-1998'), 'art26.pu', 'art26', 'paragrafo', 'Parágrafo único', 'Art. 26', '(VETADO)', '{}'::text[], 'CAPÍTULO IV – DA AÇÃO E DO PROCESSO PENAL', 82),
((select id from public.normas where slug = 'lei-9605-1998'), 'art27', null, 'artigo', 'Art. 27', 'Art. 27', 'Nos crimes ambientais de menor potencial ofensivo, a proposta de aplicação imediata de pena restritiva de direitos ou multa, prevista no art. 76 da Lei nº 9.099, de 26 de setembro de 1995, somente poderá ser formulada desde que tenha havido a prévia composição do dano ambiental, de que trata o art. 74 da mesma lei, salvo em caso de comprovada impossibilidade.', '{}'::text[], 'CAPÍTULO IV – DA AÇÃO E DO PROCESSO PENAL', 83),
((select id from public.normas where slug = 'lei-9605-1998'), 'art28', null, 'artigo', 'Art. 28', 'Art. 28', 'As disposições do art. 89 da Lei nº 9.099, de 26 de setembro de 1995, aplicam-se aos crimes de menor potencial ofensivo definidos nesta Lei, com as seguintes modificações:', '{}'::text[], 'CAPÍTULO IV – DA AÇÃO E DO PROCESSO PENAL', 84),
((select id from public.normas where slug = 'lei-9605-1998'), 'art28.inc1', 'art28', 'inciso', 'I', 'Art. 28', 'a declaração de extinção de punibilidade, de que trata o § 5° do artigo referido no caput, dependerá de laudo de constatação de reparação do dano ambiental, ressalvada a impossibilidade prevista no inciso I do § 1° do mesmo artigo;', '{}'::text[], 'CAPÍTULO IV – DA AÇÃO E DO PROCESSO PENAL', 85),
((select id from public.normas where slug = 'lei-9605-1998'), 'art28.inc2', 'art28', 'inciso', 'II', 'Art. 28', 'na hipótese de o laudo de constatação comprovar não ter sido completa a reparação, o prazo de suspensão do processo será prorrogado, até o período máximo previsto no artigo referido no caput, acrescido de mais um ano, com suspensão do prazo da prescrição;', '{}'::text[], 'CAPÍTULO IV – DA AÇÃO E DO PROCESSO PENAL', 86),
((select id from public.normas where slug = 'lei-9605-1998'), 'art28.inc3', 'art28', 'inciso', 'III', 'Art. 28', 'no período de prorrogação, não se aplicarão as condições dos incisos II, III e IV do § 1° do artigo mencionado no caput;', '{}'::text[], 'CAPÍTULO IV – DA AÇÃO E DO PROCESSO PENAL', 87),
((select id from public.normas where slug = 'lei-9605-1998'), 'art28.inc4', 'art28', 'inciso', 'IV', 'Art. 28', 'findo o prazo de prorrogação, proceder-se-á à lavratura de novo laudo de constatação de reparação do dano ambiental, podendo, conforme seu resultado, ser novamente prorrogado o período de suspensão, até o máximo previsto no inciso II deste artigo, observado o disposto no inciso III;', '{}'::text[], 'CAPÍTULO IV – DA AÇÃO E DO PROCESSO PENAL', 88),
((select id from public.normas where slug = 'lei-9605-1998'), 'art28.inc5', 'art28', 'inciso', 'V', 'Art. 28', 'esgotado o prazo máximo de prorrogação, a declaração de extinção de punibilidade dependerá de laudo de constatação que comprove ter o acusado tomado as providências necessárias à reparação integral do dano.', '{}'::text[], 'CAPÍTULO IV – DA AÇÃO E DO PROCESSO PENAL', 89),
((select id from public.normas where slug = 'lei-9605-1998'), 'art29', null, 'artigo', 'Art. 29', 'Art. 29', 'Matar, perseguir, caçar, apanhar, utilizar espécimes da fauna silvestre, nativos ou em rota migratória, sem a devida permissão, licença ou autorização da autoridade competente, ou em desacordo com a obtida:
Pena - detenção de seis meses a um ano, e multa.', '{}'::text[], 'CAPÍTULO V – DOS CRIMES CONTRA O MEIO AMBIENTE › Seção I – Dos Crimes contra a Fauna', 90),
((select id from public.normas where slug = 'lei-9605-1998'), 'art29.p1', 'art29', 'paragrafo', '§ 1º', 'Art. 29', 'Incorre nas mesmas penas:', '{}'::text[], 'CAPÍTULO V – DOS CRIMES CONTRA O MEIO AMBIENTE › Seção I – Dos Crimes contra a Fauna', 91),
((select id from public.normas where slug = 'lei-9605-1998'), 'art29.p1.inc1', 'art29.p1', 'inciso', 'I', 'Art. 29', 'quem impede a procriação da fauna, sem licença, autorização ou em desacordo com a obtida;', '{}'::text[], 'CAPÍTULO V – DOS CRIMES CONTRA O MEIO AMBIENTE › Seção I – Dos Crimes contra a Fauna', 92),
((select id from public.normas where slug = 'lei-9605-1998'), 'art29.p1.inc2', 'art29.p1', 'inciso', 'II', 'Art. 29', 'quem modifica, danifica ou destrói ninho, abrigo ou criadouro natural;', '{}'::text[], 'CAPÍTULO V – DOS CRIMES CONTRA O MEIO AMBIENTE › Seção I – Dos Crimes contra a Fauna', 93),
((select id from public.normas where slug = 'lei-9605-1998'), 'art29.p1.inc3', 'art29.p1', 'inciso', 'III', 'Art. 29', 'quem vende, expõe à venda, exporta ou adquire, guarda, tem em cativeiro ou depósito, utiliza ou transporta ovos, larvas ou espécimes da fauna silvestre, nativa ou em rota migratória, bem como produtos e objetos dela oriundos, provenientes de criadouros não autorizados ou sem a devida permissão, licença ou autorização da autoridade competente.', '{}'::text[], 'CAPÍTULO V – DOS CRIMES CONTRA O MEIO AMBIENTE › Seção I – Dos Crimes contra a Fauna', 94),
((select id from public.normas where slug = 'lei-9605-1998'), 'art29.p2', 'art29', 'paragrafo', '§ 2º', 'Art. 29', 'No caso de guarda doméstica de espécie silvestre não considerada ameaçada de extinção, pode o juiz, considerando as circunstâncias, deixar de aplicar a pena.', '{}'::text[], 'CAPÍTULO V – DOS CRIMES CONTRA O MEIO AMBIENTE › Seção I – Dos Crimes contra a Fauna', 95),
((select id from public.normas where slug = 'lei-9605-1998'), 'art29.p3', 'art29', 'paragrafo', '§ 3º', 'Art. 29', 'São espécimes da fauna silvestre todos aqueles pertencentes às espécies nativas, migratórias e quaisquer outras, aquáticas ou terrestres, que tenham todo ou parte de seu ciclo de vida ocorrendo dentro dos limites do território brasileiro, ou águas jurisdicionais brasileiras.', '{}'::text[], 'CAPÍTULO V – DOS CRIMES CONTRA O MEIO AMBIENTE › Seção I – Dos Crimes contra a Fauna', 96),
((select id from public.normas where slug = 'lei-9605-1998'), 'art29.p4', 'art29', 'paragrafo', '§ 4º', 'Art. 29', 'A pena é aumentada de metade, se o crime é praticado:', '{}'::text[], 'CAPÍTULO V – DOS CRIMES CONTRA O MEIO AMBIENTE › Seção I – Dos Crimes contra a Fauna', 97),
((select id from public.normas where slug = 'lei-9605-1998'), 'art29.p4.inc1', 'art29.p4', 'inciso', 'I', 'Art. 29', 'contra espécie rara ou considerada ameaçada de extinção, ainda que somente no local da infração;', '{}'::text[], 'CAPÍTULO V – DOS CRIMES CONTRA O MEIO AMBIENTE › Seção I – Dos Crimes contra a Fauna', 98),
((select id from public.normas where slug = 'lei-9605-1998'), 'art29.p4.inc2', 'art29.p4', 'inciso', 'II', 'Art. 29', 'em período proibido à caça;', '{}'::text[], 'CAPÍTULO V – DOS CRIMES CONTRA O MEIO AMBIENTE › Seção I – Dos Crimes contra a Fauna', 99),
((select id from public.normas where slug = 'lei-9605-1998'), 'art29.p4.inc3', 'art29.p4', 'inciso', 'III', 'Art. 29', 'durante a noite;', '{}'::text[], 'CAPÍTULO V – DOS CRIMES CONTRA O MEIO AMBIENTE › Seção I – Dos Crimes contra a Fauna', 100),
((select id from public.normas where slug = 'lei-9605-1998'), 'art29.p4.inc4', 'art29.p4', 'inciso', 'IV', 'Art. 29', 'com abuso de licença;', '{}'::text[], 'CAPÍTULO V – DOS CRIMES CONTRA O MEIO AMBIENTE › Seção I – Dos Crimes contra a Fauna', 101),
((select id from public.normas where slug = 'lei-9605-1998'), 'art29.p4.inc5', 'art29.p4', 'inciso', 'V', 'Art. 29', 'em unidade de conservação;', '{}'::text[], 'CAPÍTULO V – DOS CRIMES CONTRA O MEIO AMBIENTE › Seção I – Dos Crimes contra a Fauna', 102),
((select id from public.normas where slug = 'lei-9605-1998'), 'art29.p4.inc6', 'art29.p4', 'inciso', 'VI', 'Art. 29', 'com emprego de métodos ou instrumentos capazes de provocar destruição em massa.', '{}'::text[], 'CAPÍTULO V – DOS CRIMES CONTRA O MEIO AMBIENTE › Seção I – Dos Crimes contra a Fauna', 103),
((select id from public.normas where slug = 'lei-9605-1998'), 'art29.p5', 'art29', 'paragrafo', '§ 5º', 'Art. 29', 'A pena é aumentada até o triplo, se o crime decorre do exercício de caça profissional.', '{}'::text[], 'CAPÍTULO V – DOS CRIMES CONTRA O MEIO AMBIENTE › Seção I – Dos Crimes contra a Fauna', 104),
((select id from public.normas where slug = 'lei-9605-1998'), 'art29.p6', 'art29', 'paragrafo', '§ 6º', 'Art. 29', 'As disposições deste artigo não se aplicam aos atos de pesca.', '{}'::text[], 'CAPÍTULO V – DOS CRIMES CONTRA O MEIO AMBIENTE › Seção I – Dos Crimes contra a Fauna', 105),
((select id from public.normas where slug = 'lei-9605-1998'), 'art30', null, 'artigo', 'Art. 30', 'Art. 30', 'Exportar para o exterior peles e couros de anfíbios e répteis em bruto, sem a autorização da autoridade ambiental competente:
Pena - reclusão, de um a três anos, e multa.', '{}'::text[], 'CAPÍTULO V – DOS CRIMES CONTRA O MEIO AMBIENTE › Seção I – Dos Crimes contra a Fauna', 106),
((select id from public.normas where slug = 'lei-9605-1998'), 'art31', null, 'artigo', 'Art. 31', 'Art. 31', 'Introduzir espécime animal no País, sem parecer técnico oficial favorável e licença expedida por autoridade competente:
Pena - detenção, de três meses a um ano, e multa.', '{}'::text[], 'CAPÍTULO V – DOS CRIMES CONTRA O MEIO AMBIENTE › Seção I – Dos Crimes contra a Fauna', 107),
((select id from public.normas where slug = 'lei-9605-1998'), 'art32', null, 'artigo', 'Art. 32', 'Art. 32', 'Praticar ato de abuso, maus-tratos, ferir ou mutilar animais silvestres, domésticos ou domesticados, nativos ou exóticos:
Pena - detenção, de três meses a um ano, e multa.', array['Vide ADPF 640']::text[], 'CAPÍTULO V – DOS CRIMES CONTRA O MEIO AMBIENTE › Seção I – Dos Crimes contra a Fauna', 108),
((select id from public.normas where slug = 'lei-9605-1998'), 'art32.p1', 'art32', 'paragrafo', '§ 1º', 'Art. 32', 'Incorre nas mesmas penas quem realiza experiência dolorosa ou cruel em animal vivo, ainda que para fins didáticos ou científicos, quando existirem recursos alternativos.', array['Vide ADPF 640']::text[], 'CAPÍTULO V – DOS CRIMES CONTRA O MEIO AMBIENTE › Seção I – Dos Crimes contra a Fauna', 109),
((select id from public.normas where slug = 'lei-9605-1998'), 'art32.p1a', 'art32', 'paragrafo', '§ 1º-A', 'Art. 32', 'Quando se tratar de cão ou gato, a pena para as condutas descritas no caput deste artigo será de reclusão, de 2 (dois) a 5 (cinco) anos, multa e proibição da guarda.', array['Incluído pela Lei nº 14.064, de 2020']::text[], 'CAPÍTULO V – DOS CRIMES CONTRA O MEIO AMBIENTE › Seção I – Dos Crimes contra a Fauna', 110),
((select id from public.normas where slug = 'lei-9605-1998'), 'art32.p1b', 'art32', 'paragrafo', '§ 1º-B', 'Art. 32', 'Incorre nas mesmas penas quem realiza ou permite a realização de tatuagens e a colocação de piercings em cães e gatos, com fins estéticos.', array['Incluído pela Lei nº 15.150, de 2025']::text[], 'CAPÍTULO V – DOS CRIMES CONTRA O MEIO AMBIENTE › Seção I – Dos Crimes contra a Fauna', 111),
((select id from public.normas where slug = 'lei-9605-1998'), 'art32.p1c', 'art32', 'paragrafo', '§ 1º-C', 'Art. 32', 'Incorre nas mesmas penas quem provoca desastre ambiental que prejudique a vida, a integridade física ou o bem-estar de animais silvestres ou domésticos.', array['Incluído pela Lei nº 15.355, de 2026']::text[], 'CAPÍTULO V – DOS CRIMES CONTRA O MEIO AMBIENTE › Seção I – Dos Crimes contra a Fauna', 112),
((select id from public.normas where slug = 'lei-9605-1998'), 'art32.p2', 'art32', 'paragrafo', '§ 2º', 'Art. 32', 'A pena é aumentada de um sexto a um terço, se ocorre morte do animal.', array['Vide ADPF 640']::text[], 'CAPÍTULO V – DOS CRIMES CONTRA O MEIO AMBIENTE › Seção I – Dos Crimes contra a Fauna', 113),
((select id from public.normas where slug = 'lei-9605-1998'), 'art33', null, 'artigo', 'Art. 33', 'Art. 33', 'Provocar, pela emissão de efluentes ou carreamento de materiais, o perecimento de espécimes da fauna aquática existentes em rios, lagos, açudes, lagoas, baías ou águas jurisdicionais brasileiras:
Pena - detenção, de um a três anos, ou multa, ou ambas cumulativamente.', '{}'::text[], 'CAPÍTULO V – DOS CRIMES CONTRA O MEIO AMBIENTE › Seção I – Dos Crimes contra a Fauna', 114),
((select id from public.normas where slug = 'lei-9605-1998'), 'art33.pu', 'art33', 'paragrafo', 'Parágrafo único', 'Art. 33', 'Incorre nas mesmas penas:', '{}'::text[], 'CAPÍTULO V – DOS CRIMES CONTRA O MEIO AMBIENTE › Seção I – Dos Crimes contra a Fauna', 115),
((select id from public.normas where slug = 'lei-9605-1998'), 'art33.pu.inc1', 'art33.pu', 'inciso', 'I', 'Art. 33', 'quem causa degradação em viveiros, açudes ou estações de aqüicultura de domínio público;', '{}'::text[], 'CAPÍTULO V – DOS CRIMES CONTRA O MEIO AMBIENTE › Seção I – Dos Crimes contra a Fauna', 116),
((select id from public.normas where slug = 'lei-9605-1998'), 'art33.pu.inc2', 'art33.pu', 'inciso', 'II', 'Art. 33', 'quem explora campos naturais de invertebrados aquáticos e algas, sem licença, permissão ou autorização da autoridade competente;', '{}'::text[], 'CAPÍTULO V – DOS CRIMES CONTRA O MEIO AMBIENTE › Seção I – Dos Crimes contra a Fauna', 117),
((select id from public.normas where slug = 'lei-9605-1998'), 'art33.pu.inc3', 'art33.pu', 'inciso', 'III', 'Art. 33', 'quem fundeia embarcações ou lança detritos de qualquer natureza sobre bancos de moluscos ou corais, devidamente demarcados em carta náutica.', '{}'::text[], 'CAPÍTULO V – DOS CRIMES CONTRA O MEIO AMBIENTE › Seção I – Dos Crimes contra a Fauna', 118),
((select id from public.normas where slug = 'lei-9605-1998'), 'art34', null, 'artigo', 'Art. 34', 'Art. 34', 'Pescar em período no qual a pesca seja proibida ou em lugares interditados por órgão competente:
Pena - detenção de um ano a três anos ou multa, ou ambas as penas cumulativamente.', '{}'::text[], 'CAPÍTULO V – DOS CRIMES CONTRA O MEIO AMBIENTE › Seção I – Dos Crimes contra a Fauna', 119),
((select id from public.normas where slug = 'lei-9605-1998'), 'art34.pu', 'art34', 'paragrafo', 'Parágrafo único', 'Art. 34', 'Incorre nas mesmas penas quem:', '{}'::text[], 'CAPÍTULO V – DOS CRIMES CONTRA O MEIO AMBIENTE › Seção I – Dos Crimes contra a Fauna', 120),
((select id from public.normas where slug = 'lei-9605-1998'), 'art34.pu.inc1', 'art34.pu', 'inciso', 'I', 'Art. 34', 'pesca espécies que devam ser preservadas ou espécimes com tamanhos inferiores aos permitidos;', '{}'::text[], 'CAPÍTULO V – DOS CRIMES CONTRA O MEIO AMBIENTE › Seção I – Dos Crimes contra a Fauna', 121),
((select id from public.normas where slug = 'lei-9605-1998'), 'art34.pu.inc2', 'art34.pu', 'inciso', 'II', 'Art. 34', 'pesca quantidades superiores às permitidas, ou mediante a utilização de aparelhos, petrechos, técnicas e métodos não permitidos;', '{}'::text[], 'CAPÍTULO V – DOS CRIMES CONTRA O MEIO AMBIENTE › Seção I – Dos Crimes contra a Fauna', 122),
((select id from public.normas where slug = 'lei-9605-1998'), 'art34.pu.inc3', 'art34.pu', 'inciso', 'III', 'Art. 34', 'transporta, comercializa, beneficia ou industrializa espécimes provenientes da coleta, apanha e pesca proibidas.', '{}'::text[], 'CAPÍTULO V – DOS CRIMES CONTRA O MEIO AMBIENTE › Seção I – Dos Crimes contra a Fauna', 123),
((select id from public.normas where slug = 'lei-9605-1998'), 'art35', null, 'artigo', 'Art. 35', 'Art. 35', 'Pescar mediante a utilização de:
Pena - reclusão de um ano a cinco anos.', '{}'::text[], 'CAPÍTULO V – DOS CRIMES CONTRA O MEIO AMBIENTE › Seção I – Dos Crimes contra a Fauna', 124),
((select id from public.normas where slug = 'lei-9605-1998'), 'art35.inc1', 'art35', 'inciso', 'I', 'Art. 35', 'explosivos ou substâncias que, em contato com a água, produzam efeito semelhante;', '{}'::text[], 'CAPÍTULO V – DOS CRIMES CONTRA O MEIO AMBIENTE › Seção I – Dos Crimes contra a Fauna', 125),
((select id from public.normas where slug = 'lei-9605-1998'), 'art35.inc2', 'art35', 'inciso', 'II', 'Art. 35', 'substâncias tóxicas, ou outro meio proibido pela autoridade competente:', '{}'::text[], 'CAPÍTULO V – DOS CRIMES CONTRA O MEIO AMBIENTE › Seção I – Dos Crimes contra a Fauna', 126),
((select id from public.normas where slug = 'lei-9605-1998'), 'art36', null, 'artigo', 'Art. 36', 'Art. 36', 'Para os efeitos desta Lei, considera-se pesca todo ato tendente a retirar, extrair, coletar, apanhar, apreender ou capturar espécimes dos grupos dos peixes, crustáceos, moluscos e vegetais hidróbios, suscetíveis ou não de aproveitamento econômico, ressalvadas as espécies ameaçadas de extinção, constantes nas listas oficiais da fauna e da flora.', '{}'::text[], 'CAPÍTULO V – DOS CRIMES CONTRA O MEIO AMBIENTE › Seção I – Dos Crimes contra a Fauna', 127),
((select id from public.normas where slug = 'lei-9605-1998'), 'art37', null, 'artigo', 'Art. 37', 'Art. 37', 'Não é crime o abate de animal, quando realizado:', '{}'::text[], 'CAPÍTULO V – DOS CRIMES CONTRA O MEIO AMBIENTE › Seção I – Dos Crimes contra a Fauna', 128),
((select id from public.normas where slug = 'lei-9605-1998'), 'art37.inc1', 'art37', 'inciso', 'I', 'Art. 37', 'em estado de necessidade, para saciar a fome do agente ou de sua família;', '{}'::text[], 'CAPÍTULO V – DOS CRIMES CONTRA O MEIO AMBIENTE › Seção I – Dos Crimes contra a Fauna', 129),
((select id from public.normas where slug = 'lei-9605-1998'), 'art37.inc2', 'art37', 'inciso', 'II', 'Art. 37', 'para proteger lavouras, pomares e rebanhos da ação predatória ou destruidora de animais, desde que legal e expressamente autorizado pela autoridade competente;', '{}'::text[], 'CAPÍTULO V – DOS CRIMES CONTRA O MEIO AMBIENTE › Seção I – Dos Crimes contra a Fauna', 130),
((select id from public.normas where slug = 'lei-9605-1998'), 'art37.inc3', 'art37', 'inciso', 'III', 'Art. 37', '(VETADO)', '{}'::text[], 'CAPÍTULO V – DOS CRIMES CONTRA O MEIO AMBIENTE › Seção I – Dos Crimes contra a Fauna', 131),
((select id from public.normas where slug = 'lei-9605-1998'), 'art37.inc4', 'art37', 'inciso', 'IV', 'Art. 37', 'por ser nocivo o animal, desde que assim caracterizado pelo órgão competente.', '{}'::text[], 'CAPÍTULO V – DOS CRIMES CONTRA O MEIO AMBIENTE › Seção I – Dos Crimes contra a Fauna', 132),
((select id from public.normas where slug = 'lei-9605-1998'), 'art38', null, 'artigo', 'Art. 38', 'Art. 38', 'Destruir ou danificar floresta considerada de preservação permanente, mesmo que em formação, ou utilizá-la com infringência das normas de proteção:
Pena - detenção, de um a três anos, ou multa, ou ambas as penas cumulativamente.', '{}'::text[], 'CAPÍTULO V – DOS CRIMES CONTRA O MEIO AMBIENTE › Seção II – Dos Crimes contra a Flora', 133),
((select id from public.normas where slug = 'lei-9605-1998'), 'art38.pu', 'art38', 'paragrafo', 'Parágrafo único', 'Art. 38', 'Se o crime for culposo, a pena será reduzida à metade.', '{}'::text[], 'CAPÍTULO V – DOS CRIMES CONTRA O MEIO AMBIENTE › Seção II – Dos Crimes contra a Flora', 134),
((select id from public.normas where slug = 'lei-9605-1998'), 'art38a', null, 'artigo', 'Art. 38-A', 'Art. 38-A', 'Destruir ou danificar vegetação primária ou secundária, em estágio avançado ou médio de regeneração, do Bioma Mata Atlântica, ou utilizá-la com infringência das normas de proteção:.
Pena - detenção, de 1 (um) a 3 (três) anos, ou multa, ou ambas as penas cumulativamente.', array['Incluído pela Lei nº 11.428, de 2006','Incluído pela Lei nº 11.428, de 2006']::text[], 'CAPÍTULO V – DOS CRIMES CONTRA O MEIO AMBIENTE › Seção II – Dos Crimes contra a Flora', 135),
((select id from public.normas where slug = 'lei-9605-1998'), 'art38a.pu', 'art38a', 'paragrafo', 'Parágrafo único', 'Art. 38-A', 'Se o crime for culposo, a pena será reduzida à metade.', array['Incluído pela Lei nº 11.428, de 2006']::text[], 'CAPÍTULO V – DOS CRIMES CONTRA O MEIO AMBIENTE › Seção II – Dos Crimes contra a Flora', 136),
((select id from public.normas where slug = 'lei-9605-1998'), 'art39', null, 'artigo', 'Art. 39', 'Art. 39', 'Cortar árvores em floresta considerada de preservação permanente, sem permissão da autoridade competente:
Pena - detenção, de um a três anos, ou multa, ou ambas as penas cumulativamente.', '{}'::text[], 'CAPÍTULO V – DOS CRIMES CONTRA O MEIO AMBIENTE › Seção II – Dos Crimes contra a Flora', 137),
((select id from public.normas where slug = 'lei-9605-1998'), 'art40', null, 'artigo', 'Art. 40', 'Art. 40', 'Causar dano direto ou indireto às Unidades de Conservação e às áreas de que trata o art. 27 do Decreto nº 99.274, de 6 de junho de 1990, independentemente de sua localização:
Pena - reclusão, de um a cinco anos.', '{}'::text[], 'CAPÍTULO V – DOS CRIMES CONTRA O MEIO AMBIENTE › Seção II – Dos Crimes contra a Flora', 138),
((select id from public.normas where slug = 'lei-9605-1998'), 'art40.p1', 'art40', 'paragrafo', '§ 1º', 'Art. 40', 'Entende-se por Unidades de Conservação de Proteção Integral as Estações Ecológicas, as Reservas Biológicas, os Parques Nacionais, os Monumentos Naturais e os Refúgios de Vida Silvestre.', array['Redação dada pela Lei nº 9.985, de 2000']::text[], 'CAPÍTULO V – DOS CRIMES CONTRA O MEIO AMBIENTE › Seção II – Dos Crimes contra a Flora', 139),
((select id from public.normas where slug = 'lei-9605-1998'), 'art40.p2', 'art40', 'paragrafo', '§ 2º', 'Art. 40', 'A ocorrência de dano afetando espécies ameaçadas de extinção no interior das Unidades de Conservação de Proteção Integral será considerada circunstância agravante para a fixação da pena.', array['Redação dada pela Lei nº 9.985, de 2000']::text[], 'CAPÍTULO V – DOS CRIMES CONTRA O MEIO AMBIENTE › Seção II – Dos Crimes contra a Flora', 140),
((select id from public.normas where slug = 'lei-9605-1998'), 'art40.p3', 'art40', 'paragrafo', '§ 3º', 'Art. 40', 'Se o crime for culposo, a pena será reduzida à metade.', '{}'::text[], 'CAPÍTULO V – DOS CRIMES CONTRA O MEIO AMBIENTE › Seção II – Dos Crimes contra a Flora', 141),
((select id from public.normas where slug = 'lei-9605-1998'), 'art40a', null, 'artigo', 'Art. 40-A', 'Art. 40-A', '(VETADO)', array['Incluído pela Lei nº 9.985, de 2000']::text[], 'CAPÍTULO V – DOS CRIMES CONTRA O MEIO AMBIENTE › Seção II – Dos Crimes contra a Flora', 142),
((select id from public.normas where slug = 'lei-9605-1998'), 'art40a.p1', 'art40a', 'paragrafo', '§ 1º', 'Art. 40-A', 'Entende-se por Unidades de Conservação de Uso Sustentável as Áreas de Proteção Ambiental, as Áreas de Relevante Interesse Ecológico, as Florestas Nacionais, as Reservas Extrativistas, as Reservas de Fauna, as Reservas de Desenvolvimento Sustentável e as Reservas Particulares do Patrimônio Natural.', array['Incluído pela Lei nº 9.985, de 2000']::text[], 'CAPÍTULO V – DOS CRIMES CONTRA O MEIO AMBIENTE › Seção II – Dos Crimes contra a Flora', 143),
((select id from public.normas where slug = 'lei-9605-1998'), 'art40a.p2', 'art40a', 'paragrafo', '§ 2º', 'Art. 40-A', 'A ocorrência de dano afetando espécies ameaçadas de extinção no interior das Unidades de Conservação de Uso Sustentável será considerada circunstância agravante para a fixação da pena.', array['Incluído pela Lei nº 9.985, de 2000']::text[], 'CAPÍTULO V – DOS CRIMES CONTRA O MEIO AMBIENTE › Seção II – Dos Crimes contra a Flora', 144),
((select id from public.normas where slug = 'lei-9605-1998'), 'art40a.p3', 'art40a', 'paragrafo', '§ 3º', 'Art. 40-A', 'Se o crime for culposo, a pena será reduzida à metade.', array['Incluído pela Lei nº 9.985, de 2000']::text[], 'CAPÍTULO V – DOS CRIMES CONTRA O MEIO AMBIENTE › Seção II – Dos Crimes contra a Flora', 145),
((select id from public.normas where slug = 'lei-9605-1998'), 'art41', null, 'artigo', 'Art. 41', 'Art. 41', 'Provocar incêndio em floresta ou em demais formas de vegetação:
Pena - reclusão, de dois a quatro anos, e multa.', array['Redação dada pela Lei nº 14.944, de 2024']::text[], 'CAPÍTULO V – DOS CRIMES CONTRA O MEIO AMBIENTE › Seção II – Dos Crimes contra a Flora', 146),
((select id from public.normas where slug = 'lei-9605-1998'), 'art41.pu', 'art41', 'paragrafo', 'Parágrafo único', 'Art. 41', 'Se o crime é culposo, a pena é de detenção de seis meses a um ano, e multa.', '{}'::text[], 'CAPÍTULO V – DOS CRIMES CONTRA O MEIO AMBIENTE › Seção II – Dos Crimes contra a Flora', 147),
((select id from public.normas where slug = 'lei-9605-1998'), 'art42', null, 'artigo', 'Art. 42', 'Art. 42', 'Fabricar, vender, transportar ou soltar balões que possam provocar incêndios nas florestas e demais formas de vegetação, em áreas urbanas ou qualquer tipo de assentamento humano:
Pena - detenção de um a três anos ou multa, ou ambas as penas cumulativamente.', '{}'::text[], 'CAPÍTULO V – DOS CRIMES CONTRA O MEIO AMBIENTE › Seção II – Dos Crimes contra a Flora', 148),
((select id from public.normas where slug = 'lei-9605-1998'), 'art43', null, 'artigo', 'Art. 43', 'Art. 43', '(VETADO)', '{}'::text[], 'CAPÍTULO V – DOS CRIMES CONTRA O MEIO AMBIENTE › Seção II – Dos Crimes contra a Flora', 149),
((select id from public.normas where slug = 'lei-9605-1998'), 'art44', null, 'artigo', 'Art. 44', 'Art. 44', 'Extrair de florestas de domínio público ou consideradas de preservação permanente, sem prévia autorização, pedra, areia, cal ou qualquer espécie de minerais:
Pena - detenção, de seis meses a um ano, e multa.', '{}'::text[], 'CAPÍTULO V – DOS CRIMES CONTRA O MEIO AMBIENTE › Seção II – Dos Crimes contra a Flora', 150),
((select id from public.normas where slug = 'lei-9605-1998'), 'art45', null, 'artigo', 'Art. 45', 'Art. 45', 'Cortar ou transformar em carvão madeira de lei, assim classificada por ato do Poder Público, para fins industriais, energéticos ou para qualquer outra exploração, econômica ou não, em desacordo com as determinações legais:
Pena - reclusão, de um a dois anos, e multa.', '{}'::text[], 'CAPÍTULO V – DOS CRIMES CONTRA O MEIO AMBIENTE › Seção II – Dos Crimes contra a Flora', 151),
((select id from public.normas where slug = 'lei-9605-1998'), 'art46', null, 'artigo', 'Art. 46', 'Art. 46', 'Receber ou adquirir, para fins comerciais ou industriais, madeira, lenha, carvão e outros produtos de origem vegetal, sem exigir a exibição de licença do vendedor, outorgada pela autoridade competente, e sem munir-se da via que deverá acompanhar o produto até final beneficiamento:
Pena - detenção, de seis meses a um ano, e multa.', '{}'::text[], 'CAPÍTULO V – DOS CRIMES CONTRA O MEIO AMBIENTE › Seção II – Dos Crimes contra a Flora', 152),
((select id from public.normas where slug = 'lei-9605-1998'), 'art46.pu', 'art46', 'paragrafo', 'Parágrafo único', 'Art. 46', 'Incorre nas mesmas penas quem vende, expõe à venda, tem em depósito, transporta ou guarda madeira, lenha, carvão e outros produtos de origem vegetal, sem licença válida para todo o tempo da viagem ou do armazenamento, outorgada pela autoridade competente.', '{}'::text[], 'CAPÍTULO V – DOS CRIMES CONTRA O MEIO AMBIENTE › Seção II – Dos Crimes contra a Flora', 153),
((select id from public.normas where slug = 'lei-9605-1998'), 'art47', null, 'artigo', 'Art. 47', 'Art. 47', '(VETADO)', '{}'::text[], 'CAPÍTULO V – DOS CRIMES CONTRA O MEIO AMBIENTE › Seção II – Dos Crimes contra a Flora', 154),
((select id from public.normas where slug = 'lei-9605-1998'), 'art48', null, 'artigo', 'Art. 48', 'Art. 48', 'Impedir ou dificultar a regeneração natural de florestas e demais formas de vegetação:
Pena - detenção, de seis meses a um ano, e multa.', '{}'::text[], 'CAPÍTULO V – DOS CRIMES CONTRA O MEIO AMBIENTE › Seção II – Dos Crimes contra a Flora', 155),
((select id from public.normas where slug = 'lei-9605-1998'), 'art49', null, 'artigo', 'Art. 49', 'Art. 49', 'Destruir, danificar, lesar ou maltratar, por qualquer modo ou meio, plantas de ornamentação de logradouros públicos ou em propriedade privada alheia:
Pena - detenção, de três meses a um ano, ou multa, ou ambas as penas cumulativamente.', '{}'::text[], 'CAPÍTULO V – DOS CRIMES CONTRA O MEIO AMBIENTE › Seção II – Dos Crimes contra a Flora', 156),
((select id from public.normas where slug = 'lei-9605-1998'), 'art49.p1', 'art49', 'paragrafo', '§ 1º', 'Art. 49', 'No crime culposo, a pena é de um a seis meses, ou multa.', array['Redação dada pela Lei nº 15.299, de 2025']::text[], 'CAPÍTULO V – DOS CRIMES CONTRA O MEIO AMBIENTE › Seção II – Dos Crimes contra a Flora', 157),
((select id from public.normas where slug = 'lei-9605-1998'), 'art49.p2', 'art49', 'paragrafo', '§ 2º', 'Art. 49', 'Não incorre em crime quem procede à poda ou ao corte de árvore quando o órgão ambiental responsável não responder de maneira fundamentada, no prazo máximo de 45 (quarenta e cinco) dias, a requerimento que solicita o corte ou a poda em razão da possibilidade de ocorrência de acidente devidamente atestada por empresa ou profissional habilitado, considerada tacitamente autorizada sua realização quando esgotado o referido prazo.', array['Incluído pela Lei nº 15.299, de 2025']::text[], 'CAPÍTULO V – DOS CRIMES CONTRA O MEIO AMBIENTE › Seção II – Dos Crimes contra a Flora', 158),
((select id from public.normas where slug = 'lei-9605-1998'), 'art50', null, 'artigo', 'Art. 50', 'Art. 50', 'Destruir ou danificar florestas nativas ou plantadas ou vegetação fixadora de dunas, protetora de mangues, objeto de especial preservação:
Pena - detenção, de três meses a um ano, e multa.', '{}'::text[], 'CAPÍTULO V – DOS CRIMES CONTRA O MEIO AMBIENTE › Seção II – Dos Crimes contra a Flora', 159),
((select id from public.normas where slug = 'lei-9605-1998'), 'art50a', null, 'artigo', 'Art. 50-A', 'Art. 50-A', 'Desmatar, explorar economicamente ou degradar floresta, plantada ou nativa, em terras de domínio público ou devolutas, sem autorização do órgão competente:
Pena - reclusão de 2 (dois) a 4 (quatro) anos e multa.', array['Incluído pela Lei nº 11.284, de 2006','Incluído pela Lei nº 11.284, de 2006']::text[], 'CAPÍTULO V – DOS CRIMES CONTRA O MEIO AMBIENTE › Seção II – Dos Crimes contra a Flora', 160),
((select id from public.normas where slug = 'lei-9605-1998'), 'art50a.p1', 'art50a', 'paragrafo', '§ 1º', 'Art. 50-A', 'Não é crime a conduta praticada quando necessária à subsistência imediata pessoal do agente ou de sua família.', array['Incluído pela Lei nº 11.284, de 2006']::text[], 'CAPÍTULO V – DOS CRIMES CONTRA O MEIO AMBIENTE › Seção II – Dos Crimes contra a Flora', 161),
((select id from public.normas where slug = 'lei-9605-1998'), 'art50a.p2', 'art50a', 'paragrafo', '§ 2º', 'Art. 50-A', 'Se a área explorada for superior a 1.000 ha (mil hectares), a pena será aumentada de 1 (um) ano por milhar de hectare.', array['Incluído pela Lei nº 11.284, de 2006']::text[], 'CAPÍTULO V – DOS CRIMES CONTRA O MEIO AMBIENTE › Seção II – Dos Crimes contra a Flora', 162),
((select id from public.normas where slug = 'lei-9605-1998'), 'art51', null, 'artigo', 'Art. 51', 'Art. 51', 'Comercializar motosserra ou utilizá-la em florestas e nas demais formas de vegetação, sem licença ou registro da autoridade competente:
Pena - detenção, de três meses a um ano, e multa.', '{}'::text[], 'CAPÍTULO V – DOS CRIMES CONTRA O MEIO AMBIENTE › Seção II – Dos Crimes contra a Flora', 163),
((select id from public.normas where slug = 'lei-9605-1998'), 'art52', null, 'artigo', 'Art. 52', 'Art. 52', 'Penetrar em Unidades de Conservação conduzindo substâncias ou instrumentos próprios para caça ou para exploração de produtos ou subprodutos florestais, sem licença da autoridade competente:
Pena - detenção, de seis meses a um ano, e multa.', '{}'::text[], 'CAPÍTULO V – DOS CRIMES CONTRA O MEIO AMBIENTE › Seção II – Dos Crimes contra a Flora', 164),
((select id from public.normas where slug = 'lei-9605-1998'), 'art53', null, 'artigo', 'Art. 53', 'Art. 53', 'Nos crimes previstos nesta Seção, a pena é aumentada de um sexto a um terço se:', '{}'::text[], 'CAPÍTULO V – DOS CRIMES CONTRA O MEIO AMBIENTE › Seção II – Dos Crimes contra a Flora', 165),
((select id from public.normas where slug = 'lei-9605-1998'), 'art53.inc1', 'art53', 'inciso', 'I', 'Art. 53', 'do fato resulta a diminuição de águas naturais, a erosão do solo ou a modificação do regime climático;', '{}'::text[], 'CAPÍTULO V – DOS CRIMES CONTRA O MEIO AMBIENTE › Seção II – Dos Crimes contra a Flora', 166),
((select id from public.normas where slug = 'lei-9605-1998'), 'art53.inc2', 'art53', 'inciso', 'II', 'Art. 53', 'o crime é cometido:', '{}'::text[], 'CAPÍTULO V – DOS CRIMES CONTRA O MEIO AMBIENTE › Seção II – Dos Crimes contra a Flora', 167),
((select id from public.normas where slug = 'lei-9605-1998'), 'art53.inc2.a', 'art53.inc2', 'alinea', 'a)', 'Art. 53', 'no período de queda das sementes;', '{}'::text[], 'CAPÍTULO V – DOS CRIMES CONTRA O MEIO AMBIENTE › Seção II – Dos Crimes contra a Flora', 168),
((select id from public.normas where slug = 'lei-9605-1998'), 'art53.inc2.b', 'art53.inc2', 'alinea', 'b)', 'Art. 53', 'no período de formação de vegetações;', '{}'::text[], 'CAPÍTULO V – DOS CRIMES CONTRA O MEIO AMBIENTE › Seção II – Dos Crimes contra a Flora', 169),
((select id from public.normas where slug = 'lei-9605-1998'), 'art53.inc2.c', 'art53.inc2', 'alinea', 'c)', 'Art. 53', 'contra espécies raras ou ameaçadas de extinção, ainda que a ameaça ocorra somente no local da infração;', '{}'::text[], 'CAPÍTULO V – DOS CRIMES CONTRA O MEIO AMBIENTE › Seção II – Dos Crimes contra a Flora', 170),
((select id from public.normas where slug = 'lei-9605-1998'), 'art53.inc2.d', 'art53.inc2', 'alinea', 'd)', 'Art. 53', 'em época de seca ou inundação;', '{}'::text[], 'CAPÍTULO V – DOS CRIMES CONTRA O MEIO AMBIENTE › Seção II – Dos Crimes contra a Flora', 171),
((select id from public.normas where slug = 'lei-9605-1998'), 'art53.inc2.e', 'art53.inc2', 'alinea', 'e)', 'Art. 53', 'durante a noite, em domingo ou feriado.', '{}'::text[], 'CAPÍTULO V – DOS CRIMES CONTRA O MEIO AMBIENTE › Seção II – Dos Crimes contra a Flora', 172),
((select id from public.normas where slug = 'lei-9605-1998'), 'art54', null, 'artigo', 'Art. 54', 'Art. 54', 'Causar poluição de qualquer natureza em níveis tais que resultem ou possam resultar em danos à saúde humana, ou que provoquem a mortandade de animais ou a destruição significativa da flora:
Pena - reclusão, de um a quatro anos, e multa.', '{}'::text[], 'CAPÍTULO V – DOS CRIMES CONTRA O MEIO AMBIENTE › Seção III – Da Poluição e outros Crimes Ambientais', 173),
((select id from public.normas where slug = 'lei-9605-1998'), 'art54.p1', 'art54', 'paragrafo', '§ 1º', 'Art. 54', 'Se o crime é culposo:
Pena - detenção, de seis meses a um ano, e multa.', '{}'::text[], 'CAPÍTULO V – DOS CRIMES CONTRA O MEIO AMBIENTE › Seção III – Da Poluição e outros Crimes Ambientais', 174),
((select id from public.normas where slug = 'lei-9605-1998'), 'art54.p2', 'art54', 'paragrafo', '§ 2º', 'Art. 54', 'Se o crime:
Pena - reclusão, de um a cinco anos.', '{}'::text[], 'CAPÍTULO V – DOS CRIMES CONTRA O MEIO AMBIENTE › Seção III – Da Poluição e outros Crimes Ambientais', 175),
((select id from public.normas where slug = 'lei-9605-1998'), 'art54.p2.inc1', 'art54.p2', 'inciso', 'I', 'Art. 54', 'tornar uma área, urbana ou rural, imprópria para a ocupação humana;', '{}'::text[], 'CAPÍTULO V – DOS CRIMES CONTRA O MEIO AMBIENTE › Seção III – Da Poluição e outros Crimes Ambientais', 176),
((select id from public.normas where slug = 'lei-9605-1998'), 'art54.p2.inc2', 'art54.p2', 'inciso', 'II', 'Art. 54', 'causar poluição atmosférica que provoque a retirada, ainda que momentânea, dos habitantes das áreas afetadas, ou que cause danos diretos à saúde da população;', '{}'::text[], 'CAPÍTULO V – DOS CRIMES CONTRA O MEIO AMBIENTE › Seção III – Da Poluição e outros Crimes Ambientais', 177),
((select id from public.normas where slug = 'lei-9605-1998'), 'art54.p2.inc3', 'art54.p2', 'inciso', 'III', 'Art. 54', 'causar poluição hídrica que torne necessária a interrupção do abastecimento público de água de uma comunidade;', '{}'::text[], 'CAPÍTULO V – DOS CRIMES CONTRA O MEIO AMBIENTE › Seção III – Da Poluição e outros Crimes Ambientais', 178),
((select id from public.normas where slug = 'lei-9605-1998'), 'art54.p2.inc4', 'art54.p2', 'inciso', 'IV', 'Art. 54', 'dificultar ou impedir o uso público das praias;', '{}'::text[], 'CAPÍTULO V – DOS CRIMES CONTRA O MEIO AMBIENTE › Seção III – Da Poluição e outros Crimes Ambientais', 179),
((select id from public.normas where slug = 'lei-9605-1998'), 'art54.p2.inc5', 'art54.p2', 'inciso', 'V', 'Art. 54', 'ocorrer por lançamento de resíduos sólidos, líquidos ou gasosos, ou detritos, óleos ou substâncias oleosas, em desacordo com as exigências estabelecidas em leis ou regulamentos:', '{}'::text[], 'CAPÍTULO V – DOS CRIMES CONTRA O MEIO AMBIENTE › Seção III – Da Poluição e outros Crimes Ambientais', 180),
((select id from public.normas where slug = 'lei-9605-1998'), 'art54.p3', 'art54', 'paragrafo', '§ 3º', 'Art. 54', 'Incorre nas mesmas penas previstas no parágrafo anterior quem deixar de adotar, quando assim o exigir a autoridade competente, medidas de precaução em caso de risco de dano ambiental grave ou irreversível.', '{}'::text[], 'CAPÍTULO V – DOS CRIMES CONTRA O MEIO AMBIENTE › Seção III – Da Poluição e outros Crimes Ambientais', 181),
((select id from public.normas where slug = 'lei-9605-1998'), 'art55', null, 'artigo', 'Art. 55', 'Art. 55', 'Executar pesquisa, lavra ou extração de recursos minerais sem a competente autorização, permissão, concessão ou licença, ou em desacordo com a obtida:
Pena - detenção, de seis meses a um ano, e multa.', '{}'::text[], 'CAPÍTULO V – DOS CRIMES CONTRA O MEIO AMBIENTE › Seção III – Da Poluição e outros Crimes Ambientais', 182),
((select id from public.normas where slug = 'lei-9605-1998'), 'art55.pu', 'art55', 'paragrafo', 'Parágrafo único', 'Art. 55', 'Nas mesmas penas incorre quem deixa de recuperar a área pesquisada ou explorada, nos termos da autorização, permissão, licença, concessão ou determinação do órgão competente.', '{}'::text[], 'CAPÍTULO V – DOS CRIMES CONTRA O MEIO AMBIENTE › Seção III – Da Poluição e outros Crimes Ambientais', 183),
((select id from public.normas where slug = 'lei-9605-1998'), 'art56', null, 'artigo', 'Art. 56', 'Art. 56', 'Produzir, processar, embalar, importar, exportar, comercializar, fornecer, transportar, armazenar, guardar, ter em depósito ou usar produto ou substância tóxica, perigosa ou nociva à saúde humana ou ao meio ambiente, em desacordo com as exigências estabelecidas em leis ou nos seus regulamentos:
Pena - reclusão, de um a quatro anos, e multa.', '{}'::text[], 'CAPÍTULO V – DOS CRIMES CONTRA O MEIO AMBIENTE › Seção III – Da Poluição e outros Crimes Ambientais', 184),
((select id from public.normas where slug = 'lei-9605-1998'), 'art56.p1', 'art56', 'paragrafo', '§ 1º', 'Art. 56', 'Nas mesmas penas incorre quem:', array['Redação dada pela Lei nº 12.305, de 2010']::text[], 'CAPÍTULO V – DOS CRIMES CONTRA O MEIO AMBIENTE › Seção III – Da Poluição e outros Crimes Ambientais', 185),
((select id from public.normas where slug = 'lei-9605-1998'), 'art56.p1.inc1', 'art56.p1', 'inciso', 'I', 'Art. 56', 'abandona os produtos ou substâncias referidos no caput ou os utiliza em desacordo com as normas ambientais ou de segurança;', array['Incluído pela Lei nº 12.305, de 2010']::text[], 'CAPÍTULO V – DOS CRIMES CONTRA O MEIO AMBIENTE › Seção III – Da Poluição e outros Crimes Ambientais', 186),
((select id from public.normas where slug = 'lei-9605-1998'), 'art56.p1.inc2', 'art56.p1', 'inciso', 'II', 'Art. 56', 'manipula, acondiciona, armazena, coleta, transporta, reutiliza, recicla ou dá destinação final a resíduos perigosos de forma diversa da estabelecida em lei ou regulamento.', array['Incluído pela Lei nº 12.305, de 2010']::text[], 'CAPÍTULO V – DOS CRIMES CONTRA O MEIO AMBIENTE › Seção III – Da Poluição e outros Crimes Ambientais', 187),
((select id from public.normas where slug = 'lei-9605-1998'), 'art56.p2', 'art56', 'paragrafo', '§ 2º', 'Art. 56', 'Se o produto ou a substância for nuclear ou radioativa, a pena é aumentada de um sexto a um terço.', '{}'::text[], 'CAPÍTULO V – DOS CRIMES CONTRA O MEIO AMBIENTE › Seção III – Da Poluição e outros Crimes Ambientais', 188),
((select id from public.normas where slug = 'lei-9605-1998'), 'art56.p3', 'art56', 'paragrafo', '§ 3º', 'Art. 56', 'Se o crime é culposo:
Pena - detenção, de seis meses a um ano, e multa.', '{}'::text[], 'CAPÍTULO V – DOS CRIMES CONTRA O MEIO AMBIENTE › Seção III – Da Poluição e outros Crimes Ambientais', 189),
((select id from public.normas where slug = 'lei-9605-1998'), 'art57', null, 'artigo', 'Art. 57', 'Art. 57', '(VETADO)', '{}'::text[], 'CAPÍTULO V – DOS CRIMES CONTRA O MEIO AMBIENTE › Seção III – Da Poluição e outros Crimes Ambientais', 190),
((select id from public.normas where slug = 'lei-9605-1998'), 'art58', null, 'artigo', 'Art. 58', 'Art. 58', 'Nos crimes dolosos previstos nesta Seção, as penas serão aumentadas:', '{}'::text[], 'CAPÍTULO V – DOS CRIMES CONTRA O MEIO AMBIENTE › Seção III – Da Poluição e outros Crimes Ambientais', 191),
((select id from public.normas where slug = 'lei-9605-1998'), 'art58.inc1', 'art58', 'inciso', 'I', 'Art. 58', 'de um sexto a um terço, se resulta dano irreversível à flora ou ao meio ambiente em geral;', '{}'::text[], 'CAPÍTULO V – DOS CRIMES CONTRA O MEIO AMBIENTE › Seção III – Da Poluição e outros Crimes Ambientais', 192),
((select id from public.normas where slug = 'lei-9605-1998'), 'art58.inc2', 'art58', 'inciso', 'II', 'Art. 58', 'de um terço até a metade, se resulta lesão corporal de natureza grave em outrem;', '{}'::text[], 'CAPÍTULO V – DOS CRIMES CONTRA O MEIO AMBIENTE › Seção III – Da Poluição e outros Crimes Ambientais', 193),
((select id from public.normas where slug = 'lei-9605-1998'), 'art58.inc3', 'art58', 'inciso', 'III', 'Art. 58', 'até o dobro, se resultar a morte de outrem.', '{}'::text[], 'CAPÍTULO V – DOS CRIMES CONTRA O MEIO AMBIENTE › Seção III – Da Poluição e outros Crimes Ambientais', 194),
((select id from public.normas where slug = 'lei-9605-1998'), 'art58.pu', 'art58', 'paragrafo', 'Parágrafo único', 'Art. 58', 'As penalidades previstas neste artigo somente serão aplicadas se do fato não resultar crime mais grave.', '{}'::text[], 'CAPÍTULO V – DOS CRIMES CONTRA O MEIO AMBIENTE › Seção III – Da Poluição e outros Crimes Ambientais', 195),
((select id from public.normas where slug = 'lei-9605-1998'), 'art59', null, 'artigo', 'Art. 59', 'Art. 59', '(VETADO)', '{}'::text[], 'CAPÍTULO V – DOS CRIMES CONTRA O MEIO AMBIENTE › Seção III – Da Poluição e outros Crimes Ambientais', 196),
((select id from public.normas where slug = 'lei-9605-1998'), 'art60', null, 'artigo', 'Art. 60', 'Art. 60', 'Construir, reformar, ampliar, instalar ou fazer funcionar, em qualquer parte do território nacional, estabelecimentos, obras ou serviços potencialmente poluidores, sem licença ou autorização dos órgãos ambientais competentes, ou contrariando as normas legais e regulamentares pertinentes:
Pena - detenção, de 6 (seis) meses a 2 (dois) anos, ou multa, ou ambas as penas, cumulativamente.', array['Redação dada pela Lei nº 15.190, de 2025']::text[], 'CAPÍTULO V – DOS CRIMES CONTRA O MEIO AMBIENTE › Seção III – Da Poluição e outros Crimes Ambientais', 197),
((select id from public.normas where slug = 'lei-9605-1998'), 'art60.pu', 'art60', 'paragrafo', 'Parágrafo único', 'Art. 60', 'A pena é aumentada até o dobro se o licenciamento da atividade ou do empreendimento for sujeito ao Estudo Prévio de Impacto Ambiental.', array['Incluído pela Lei nº 15.190, de 2025']::text[], 'CAPÍTULO V – DOS CRIMES CONTRA O MEIO AMBIENTE › Seção III – Da Poluição e outros Crimes Ambientais', 198),
((select id from public.normas where slug = 'lei-9605-1998'), 'art61', null, 'artigo', 'Art. 61', 'Art. 61', 'Disseminar doença ou praga ou espécies que possam causar dano à agricultura, à pecuária, à fauna, à flora ou aos ecossistemas:
Pena - reclusão, de um a quatro anos, e multa.', '{}'::text[], 'CAPÍTULO V – DOS CRIMES CONTRA O MEIO AMBIENTE › Seção III – Da Poluição e outros Crimes Ambientais', 199),
((select id from public.normas where slug = 'lei-9605-1998'), 'art62', null, 'artigo', 'Art. 62', 'Art. 62', 'Destruir, inutilizar ou deteriorar:
Pena - reclusão, de um a três anos, e multa.', '{}'::text[], 'CAPÍTULO V – DOS CRIMES CONTRA O MEIO AMBIENTE › Seção IV – Dos Crimes contra o Ordenamento Urbano e o Patrimônio Cultural', 200),
((select id from public.normas where slug = 'lei-9605-1998'), 'art62.inc1', 'art62', 'inciso', 'I', 'Art. 62', 'bem especialmente protegido por lei, ato administrativo ou decisão judicial;', '{}'::text[], 'CAPÍTULO V – DOS CRIMES CONTRA O MEIO AMBIENTE › Seção IV – Dos Crimes contra o Ordenamento Urbano e o Patrimônio Cultural', 201),
((select id from public.normas where slug = 'lei-9605-1998'), 'art62.inc2', 'art62', 'inciso', 'II', 'Art. 62', 'arquivo, registro, museu, biblioteca, pinacoteca, instalação científica ou similar protegido por lei, ato administrativo ou decisão judicial:', '{}'::text[], 'CAPÍTULO V – DOS CRIMES CONTRA O MEIO AMBIENTE › Seção IV – Dos Crimes contra o Ordenamento Urbano e o Patrimônio Cultural', 202),
((select id from public.normas where slug = 'lei-9605-1998'), 'art62.pu', 'art62', 'paragrafo', 'Parágrafo único', 'Art. 62', 'Se o crime for culposo, a pena é de seis meses a um ano de detenção, sem prejuízo da multa.', '{}'::text[], 'CAPÍTULO V – DOS CRIMES CONTRA O MEIO AMBIENTE › Seção IV – Dos Crimes contra o Ordenamento Urbano e o Patrimônio Cultural', 203),
((select id from public.normas where slug = 'lei-9605-1998'), 'art63', null, 'artigo', 'Art. 63', 'Art. 63', 'Alterar o aspecto ou estrutura de edificação ou local especialmente protegido por lei, ato administrativo ou decisão judicial, em razão de seu valor paisagístico, ecológico, turístico, artístico, histórico, cultural, religioso, arqueológico, etnográfico ou monumental, sem autorização da autoridade competente ou em desacordo com a concedida:
Pena - reclusão, de um a três anos, e multa.', '{}'::text[], 'CAPÍTULO V – DOS CRIMES CONTRA O MEIO AMBIENTE › Seção IV – Dos Crimes contra o Ordenamento Urbano e o Patrimônio Cultural', 204),
((select id from public.normas where slug = 'lei-9605-1998'), 'art64', null, 'artigo', 'Art. 64', 'Art. 64', 'Promover construção em solo não edificável, ou no seu entorno, assim considerado em razão de seu valor paisagístico, ecológico, artístico, turístico, histórico, cultural, religioso, arqueológico, etnográfico ou monumental, sem autorização da autoridade competente ou em desacordo com a concedida:
Pena - detenção, de seis meses a um ano, e multa.', '{}'::text[], 'CAPÍTULO V – DOS CRIMES CONTRA O MEIO AMBIENTE › Seção IV – Dos Crimes contra o Ordenamento Urbano e o Patrimônio Cultural', 205),
((select id from public.normas where slug = 'lei-9605-1998'), 'art65', null, 'artigo', 'Art. 65', 'Art. 65', 'Pichar ou por outro meio conspurcar edificação ou monumento urbano:
Pena - detenção, de 3 (três) meses a 1 (um) ano, e multa.', array['Redação dada pela Lei nº 12.408, de 2011','Redação dada pela Lei nº 12.408, de 2011']::text[], 'CAPÍTULO V – DOS CRIMES CONTRA O MEIO AMBIENTE › Seção IV – Dos Crimes contra o Ordenamento Urbano e o Patrimônio Cultural', 206),
((select id from public.normas where slug = 'lei-9605-1998'), 'art65.p1', 'art65', 'paragrafo', '§ 1º', 'Art. 65', 'Se o ato for realizado em monumento ou coisa tombada em virtude do seu valor artístico, arqueológico ou histórico, a pena é de 6 (seis) meses a 1 (um) ano de detenção e multa.', array['Renumerado do parágrafo único pela Lei nº 12.408, de 2011']::text[], 'CAPÍTULO V – DOS CRIMES CONTRA O MEIO AMBIENTE › Seção IV – Dos Crimes contra o Ordenamento Urbano e o Patrimônio Cultural', 207),
((select id from public.normas where slug = 'lei-9605-1998'), 'art65.p2', 'art65', 'paragrafo', '§ 2º', 'Art. 65', 'Não constitui crime a prática de grafite realizada com o objetivo de valorizar o patrimônio público ou privado mediante manifestação artística, desde que consentida pelo proprietário e, quando couber, pelo locatário ou arrendatário do bem privado e, no caso de bem público, com a autorização do órgão competente e a observância das posturas municipais e das normas editadas pelos órgãos governamentais responsáveis pela preservação e conservação do patrimônio histórico e artístico nacional.', array['Incluído pela Lei nº 12.408, de 2011']::text[], 'CAPÍTULO V – DOS CRIMES CONTRA O MEIO AMBIENTE › Seção IV – Dos Crimes contra o Ordenamento Urbano e o Patrimônio Cultural', 208),
((select id from public.normas where slug = 'lei-9605-1998'), 'art66', null, 'artigo', 'Art. 66', 'Art. 66', 'Fazer o funcionário público afirmação falsa ou enganosa, omitir a verdade, sonegar informações ou dados técnico-científicos em procedimentos de autorização ou de licenciamento ambiental:
Pena - reclusão, de um a três anos, e multa.', '{}'::text[], 'CAPÍTULO V – DOS CRIMES CONTRA O MEIO AMBIENTE › Seção V – Dos Crimes contra a Administração Ambiental', 209),
((select id from public.normas where slug = 'lei-9605-1998'), 'art67', null, 'artigo', 'Art. 67', 'Art. 67', 'Conceder dolosamente o funcionário público licença, autorização ou permissão que sabe estar em desacordo com as normas ambientais a atividades, obras ou serviços cuja realização depende de ato autorizativo do poder público:
Pena - detenção, de 1 (um) a 3 (três) anos, e multa.', array['Redação dada pela Lei nº 15.190, de 2025','Revogado pela Lei nº 15.190, de 2025','Redação dada pela Lei nº 15.190, de 2025']::text[], 'CAPÍTULO V – DOS CRIMES CONTRA O MEIO AMBIENTE › Seção V – Dos Crimes contra a Administração Ambiental', 210),
((select id from public.normas where slug = 'lei-9605-1998'), 'art67.pu', 'art67', 'paragrafo', 'Parágrafo único', 'Art. 67', '', array['Revogado','Redação dada pela Lei nº 15.190, de 2025']::text[], 'CAPÍTULO V – DOS CRIMES CONTRA O MEIO AMBIENTE › Seção V – Dos Crimes contra a Administração Ambiental', 211),
((select id from public.normas where slug = 'lei-9605-1998'), 'art68', null, 'artigo', 'Art. 68', 'Art. 68', 'Deixar, aquele que tiver o dever legal ou contratual de fazê-lo, de cumprir obrigação de relevante interesse ambiental:
Pena - detenção, de um a três anos, e multa.', '{}'::text[], 'CAPÍTULO V – DOS CRIMES CONTRA O MEIO AMBIENTE › Seção V – Dos Crimes contra a Administração Ambiental', 212),
((select id from public.normas where slug = 'lei-9605-1998'), 'art68.pu', 'art68', 'paragrafo', 'Parágrafo único', 'Art. 68', 'Se o crime é culposo, a pena é de três meses a um ano, sem prejuízo da multa.', '{}'::text[], 'CAPÍTULO V – DOS CRIMES CONTRA O MEIO AMBIENTE › Seção V – Dos Crimes contra a Administração Ambiental', 213),
((select id from public.normas where slug = 'lei-9605-1998'), 'art69', null, 'artigo', 'Art. 69', 'Art. 69', 'Obstar ou dificultar a ação fiscalizadora do Poder Público no trato de questões ambientais:
Pena - detenção, de um a três anos, e multa.', '{}'::text[], 'CAPÍTULO V – DOS CRIMES CONTRA O MEIO AMBIENTE › Seção V – Dos Crimes contra a Administração Ambiental', 214),
((select id from public.normas where slug = 'lei-9605-1998'), 'art69a', null, 'artigo', 'Art. 69-A', 'Art. 69-A', 'Elaborar ou apresentar, no licenciamento, concessão florestal ou qualquer outro procedimento administrativo, estudo, laudo ou relatório ambiental total ou parcialmente falso ou enganoso, inclusive por omissão:
Pena - reclusão, de 3 (três) a 6 (seis) anos, e multa.', array['Incluído pela Lei nº 11.284, de 2006','Incluído pela Lei nº 11.284, de 2006']::text[], 'CAPÍTULO V – DOS CRIMES CONTRA O MEIO AMBIENTE › Seção V – Dos Crimes contra a Administração Ambiental', 215),
((select id from public.normas where slug = 'lei-9605-1998'), 'art69a.p1', 'art69a', 'paragrafo', '§ 1º', 'Art. 69-A', 'Se o crime é culposo:
Pena - detenção, de 1 (um) a 3 (três) anos.', array['Incluído pela Lei nº 11.284, de 2006','Incluído pela Lei nº 11.284, de 2006']::text[], 'CAPÍTULO V – DOS CRIMES CONTRA O MEIO AMBIENTE › Seção V – Dos Crimes contra a Administração Ambiental', 216),
((select id from public.normas where slug = 'lei-9605-1998'), 'art69a.p2', 'art69a', 'paragrafo', '§ 2º', 'Art. 69-A', 'A pena é aumentada de 1/3 (um terço) a 2/3 (dois terços), se há dano significativo ao meio ambiente, em decorrência do uso da informação falsa, incompleta ou enganosa.', array['Incluído pela Lei nº 11.284, de 2006']::text[], 'CAPÍTULO V – DOS CRIMES CONTRA O MEIO AMBIENTE › Seção V – Dos Crimes contra a Administração Ambiental', 217),
((select id from public.normas where slug = 'lei-9605-1998'), 'art70', null, 'artigo', 'Art. 70', 'Art. 70', 'Considera-se infração administrativa ambiental toda ação ou omissão que viole as regras jurídicas de uso, gozo, promoção, proteção e recuperação do meio ambiente.', '{}'::text[], 'CAPÍTULO VI – DA INFRAÇÃO ADMINISTRATIVA', 218),
((select id from public.normas where slug = 'lei-9605-1998'), 'art70.p1', 'art70', 'paragrafo', '§ 1º', 'Art. 70', 'São autoridades competentes para lavrar auto de infração ambiental e instaurar processo administrativo os funcionários de órgãos ambientais integrantes do Sistema Nacional de Meio Ambiente - SISNAMA, designados para as atividades de fiscalização, bem como os agentes das Capitanias dos Portos, do Ministério da Marinha.', '{}'::text[], 'CAPÍTULO VI – DA INFRAÇÃO ADMINISTRATIVA', 219),
((select id from public.normas where slug = 'lei-9605-1998'), 'art70.p2', 'art70', 'paragrafo', '§ 2º', 'Art. 70', 'Qualquer pessoa, constatando infração ambiental, poderá dirigir representação às autoridades relacionadas no parágrafo anterior, para efeito do exercício do seu poder de polícia.', '{}'::text[], 'CAPÍTULO VI – DA INFRAÇÃO ADMINISTRATIVA', 220),
((select id from public.normas where slug = 'lei-9605-1998'), 'art70.p3', 'art70', 'paragrafo', '§ 3º', 'Art. 70', 'A autoridade ambiental que tiver conhecimento de infração ambiental é obrigada a promover a sua apuração imediata, mediante processo administrativo próprio, sob pena de co-responsabilidade.', '{}'::text[], 'CAPÍTULO VI – DA INFRAÇÃO ADMINISTRATIVA', 221),
((select id from public.normas where slug = 'lei-9605-1998'), 'art70.p4', 'art70', 'paragrafo', '§ 4º', 'Art. 70', 'As infrações ambientais são apuradas em processo administrativo próprio, assegurado o direito de ampla defesa e o contraditório, observadas as disposições desta Lei.', '{}'::text[], 'CAPÍTULO VI – DA INFRAÇÃO ADMINISTRATIVA', 222),
((select id from public.normas where slug = 'lei-9605-1998'), 'art71', null, 'artigo', 'Art. 71', 'Art. 71', 'O processo administrativo para apuração de infração ambiental deve observar os seguintes prazos máximos:', '{}'::text[], 'CAPÍTULO VI – DA INFRAÇÃO ADMINISTRATIVA', 223),
((select id from public.normas where slug = 'lei-9605-1998'), 'art71.inc1', 'art71', 'inciso', 'I', 'Art. 71', 'vinte dias para o infrator oferecer defesa ou impugnação contra o auto de infração, contados da data da ciência da autuação;', '{}'::text[], 'CAPÍTULO VI – DA INFRAÇÃO ADMINISTRATIVA', 224),
((select id from public.normas where slug = 'lei-9605-1998'), 'art71.inc2', 'art71', 'inciso', 'II', 'Art. 71', 'trinta dias para a autoridade competente julgar o auto de infração, contados da data da sua lavratura, apresentada ou não a defesa ou impugnação;', '{}'::text[], 'CAPÍTULO VI – DA INFRAÇÃO ADMINISTRATIVA', 225),
((select id from public.normas where slug = 'lei-9605-1998'), 'art71.inc3', 'art71', 'inciso', 'III', 'Art. 71', 'vinte dias para o infrator recorrer da decisão condenatória à instância superior do Sistema Nacional do Meio Ambiente - SISNAMA, ou à Diretoria de Portos e Costas, do Ministério da Marinha, de acordo com o tipo de autuação;', '{}'::text[], 'CAPÍTULO VI – DA INFRAÇÃO ADMINISTRATIVA', 226),
((select id from public.normas where slug = 'lei-9605-1998'), 'art71.inc4', 'art71', 'inciso', 'IV', 'Art. 71', 'cinco dias para o pagamento de multa, contados da data do recebimento da notificação.', '{}'::text[], 'CAPÍTULO VI – DA INFRAÇÃO ADMINISTRATIVA', 227),
((select id from public.normas where slug = 'lei-9605-1998'), 'art72', null, 'artigo', 'Art. 72', 'Art. 72', 'As infrações administrativas são punidas com as seguintes sanções, observado o disposto no art. 6º:', '{}'::text[], 'CAPÍTULO VI – DA INFRAÇÃO ADMINISTRATIVA', 228),
((select id from public.normas where slug = 'lei-9605-1998'), 'art72.inc1', 'art72', 'inciso', 'I', 'Art. 72', 'advertência;', '{}'::text[], 'CAPÍTULO VI – DA INFRAÇÃO ADMINISTRATIVA', 229),
((select id from public.normas where slug = 'lei-9605-1998'), 'art72.inc2', 'art72', 'inciso', 'II', 'Art. 72', 'multa simples;', '{}'::text[], 'CAPÍTULO VI – DA INFRAÇÃO ADMINISTRATIVA', 230),
((select id from public.normas where slug = 'lei-9605-1998'), 'art72.inc3', 'art72', 'inciso', 'III', 'Art. 72', 'multa diária;', '{}'::text[], 'CAPÍTULO VI – DA INFRAÇÃO ADMINISTRATIVA', 231),
((select id from public.normas where slug = 'lei-9605-1998'), 'art72.inc4', 'art72', 'inciso', 'IV', 'Art. 72', 'apreensão dos animais, produtos e subprodutos da fauna e flora, instrumentos, petrechos, equipamentos ou veículos de qualquer natureza utilizados na infração;', '{}'::text[], 'CAPÍTULO VI – DA INFRAÇÃO ADMINISTRATIVA', 232),
((select id from public.normas where slug = 'lei-9605-1998'), 'art72.inc5', 'art72', 'inciso', 'V', 'Art. 72', 'destruição ou inutilização do produto;', '{}'::text[], 'CAPÍTULO VI – DA INFRAÇÃO ADMINISTRATIVA', 233),
((select id from public.normas where slug = 'lei-9605-1998'), 'art72.inc6', 'art72', 'inciso', 'VI', 'Art. 72', 'suspensão de venda e fabricação do produto;', '{}'::text[], 'CAPÍTULO VI – DA INFRAÇÃO ADMINISTRATIVA', 234),
((select id from public.normas where slug = 'lei-9605-1998'), 'art72.inc7', 'art72', 'inciso', 'VII', 'Art. 72', 'embargo de obra ou atividade;', '{}'::text[], 'CAPÍTULO VI – DA INFRAÇÃO ADMINISTRATIVA', 235),
((select id from public.normas where slug = 'lei-9605-1998'), 'art72.inc8', 'art72', 'inciso', 'VIII', 'Art. 72', 'demolição de obra;', '{}'::text[], 'CAPÍTULO VI – DA INFRAÇÃO ADMINISTRATIVA', 236),
((select id from public.normas where slug = 'lei-9605-1998'), 'art72.inc9', 'art72', 'inciso', 'IX', 'Art. 72', 'suspensão parcial ou total de atividades;', '{}'::text[], 'CAPÍTULO VI – DA INFRAÇÃO ADMINISTRATIVA', 237),
((select id from public.normas where slug = 'lei-9605-1998'), 'art72.inc10', 'art72', 'inciso', 'X', 'Art. 72', '(VETADO)', '{}'::text[], 'CAPÍTULO VI – DA INFRAÇÃO ADMINISTRATIVA', 238),
((select id from public.normas where slug = 'lei-9605-1998'), 'art72.inc11', 'art72', 'inciso', 'XI', 'Art. 72', 'restritiva de direitos.', '{}'::text[], 'CAPÍTULO VI – DA INFRAÇÃO ADMINISTRATIVA', 239),
((select id from public.normas where slug = 'lei-9605-1998'), 'art72.p1', 'art72', 'paragrafo', '§ 1º', 'Art. 72', 'Se o infrator cometer, simultaneamente, duas ou mais infrações, ser-lhe-ão aplicadas, cumulativamente, as sanções a elas cominadas.', '{}'::text[], 'CAPÍTULO VI – DA INFRAÇÃO ADMINISTRATIVA', 240),
((select id from public.normas where slug = 'lei-9605-1998'), 'art72.p2', 'art72', 'paragrafo', '§ 2º', 'Art. 72', 'A advertência será aplicada pela inobservância das disposições desta Lei e da legislação em vigor, ou de preceitos regulamentares, sem prejuízo das demais sanções previstas neste artigo.', '{}'::text[], 'CAPÍTULO VI – DA INFRAÇÃO ADMINISTRATIVA', 241),
((select id from public.normas where slug = 'lei-9605-1998'), 'art72.p3', 'art72', 'paragrafo', '§ 3º', 'Art. 72', 'A multa simples será aplicada sempre que o agente, por negligência ou dolo:', '{}'::text[], 'CAPÍTULO VI – DA INFRAÇÃO ADMINISTRATIVA', 242),
((select id from public.normas where slug = 'lei-9605-1998'), 'art72.p3.inc1', 'art72.p3', 'inciso', 'I', 'Art. 72', 'advertido por irregularidades que tenham sido praticadas, deixar de saná-las, no prazo assinalado por órgão competente do SISNAMA ou pela Capitania dos Portos, do Ministério da Marinha;', '{}'::text[], 'CAPÍTULO VI – DA INFRAÇÃO ADMINISTRATIVA', 243),
((select id from public.normas where slug = 'lei-9605-1998'), 'art72.p3.inc2', 'art72.p3', 'inciso', 'II', 'Art. 72', 'opuser embaraço à fiscalização dos órgãos do SISNAMA ou da Capitania dos Portos, do Ministério da Marinha.', '{}'::text[], 'CAPÍTULO VI – DA INFRAÇÃO ADMINISTRATIVA', 244),
((select id from public.normas where slug = 'lei-9605-1998'), 'art72.p4', 'art72', 'paragrafo', '§ 4º', 'Art. 72', 'A multa simples pode ser convertida em serviços de preservação, melhoria e recuperação da qualidade do meio ambiente.', '{}'::text[], 'CAPÍTULO VI – DA INFRAÇÃO ADMINISTRATIVA', 245),
((select id from public.normas where slug = 'lei-9605-1998'), 'art72.p5', 'art72', 'paragrafo', '§ 5º', 'Art. 72', 'A multa diária será aplicada sempre que o cometimento da infração se prolongar no tempo.', '{}'::text[], 'CAPÍTULO VI – DA INFRAÇÃO ADMINISTRATIVA', 246),
((select id from public.normas where slug = 'lei-9605-1998'), 'art72.p6', 'art72', 'paragrafo', '§ 6º', 'Art. 72', 'A apreensão e destruição referidas nos incisos IV e V do caput obedecerão ao disposto no art. 25 desta Lei.', '{}'::text[], 'CAPÍTULO VI – DA INFRAÇÃO ADMINISTRATIVA', 247),
((select id from public.normas where slug = 'lei-9605-1998'), 'art72.p7', 'art72', 'paragrafo', '§ 7º', 'Art. 72', 'As sanções indicadas nos incisos VI a IX do caput serão aplicadas quando o produto, a obra, a atividade ou o estabelecimento não estiverem obedecendo às prescrições legais ou regulamentares.', '{}'::text[], 'CAPÍTULO VI – DA INFRAÇÃO ADMINISTRATIVA', 248),
((select id from public.normas where slug = 'lei-9605-1998'), 'art72.p8', 'art72', 'paragrafo', '§ 8º', 'Art. 72', 'As sanções restritivas de direito são:', '{}'::text[], 'CAPÍTULO VI – DA INFRAÇÃO ADMINISTRATIVA', 249),
((select id from public.normas where slug = 'lei-9605-1998'), 'art72.p8.inc1', 'art72.p8', 'inciso', 'I', 'Art. 72', 'suspensão de registro, licença ou autorização;', '{}'::text[], 'CAPÍTULO VI – DA INFRAÇÃO ADMINISTRATIVA', 250),
((select id from public.normas where slug = 'lei-9605-1998'), 'art72.p8.inc2', 'art72.p8', 'inciso', 'II', 'Art. 72', 'cancelamento de registro, licença ou autorização;', '{}'::text[], 'CAPÍTULO VI – DA INFRAÇÃO ADMINISTRATIVA', 251),
((select id from public.normas where slug = 'lei-9605-1998'), 'art72.p8.inc3', 'art72.p8', 'inciso', 'III', 'Art. 72', 'perda ou restrição de incentivos e benefícios fiscais;', '{}'::text[], 'CAPÍTULO VI – DA INFRAÇÃO ADMINISTRATIVA', 252),
((select id from public.normas where slug = 'lei-9605-1998'), 'art72.p8.inc4', 'art72.p8', 'inciso', 'IV', 'Art. 72', 'perda ou suspensão da participação em linhas de financiamento em estabelecimentos oficiais de crédito;', '{}'::text[], 'CAPÍTULO VI – DA INFRAÇÃO ADMINISTRATIVA', 253),
((select id from public.normas where slug = 'lei-9605-1998'), 'art72.p8.inc5', 'art72.p8', 'inciso', 'V', 'Art. 72', 'proibição de contratar com a Administração Pública, pelo período de até três anos.', '{}'::text[], 'CAPÍTULO VI – DA INFRAÇÃO ADMINISTRATIVA', 254),
((select id from public.normas where slug = 'lei-9605-1998'), 'art73', null, 'artigo', 'Art. 73', 'Art. 73', 'Os valores arrecadados em pagamento de multas por infração ambiental serão revertidos ao Fundo Nacional do Meio Ambiente, criado pela Lei nº 7.797, de 10 de julho de 1989, ao Fundo Naval, criado pelo Decreto nº 20.923, de 8 de janeiro de 1932, ao Fundo Nacional para Calamidades Públicas, Proteção e Defesa Civil (Funcap), criado pela Lei nº 12.340, de 1º de dezembro de 2010, e aos fundos estaduais ou municipais de meio ambiente, ou correlatos, conforme dispuser o órgão arrecadador.', array['Redação dada pela Lei nº 14.691, de 2023']::text[], 'CAPÍTULO VI – DA INFRAÇÃO ADMINISTRATIVA', 255),
((select id from public.normas where slug = 'lei-9605-1998'), 'art73.p1', 'art73', 'paragrafo', '§ 1º', 'Art. 73', 'Reverterão ao Fundo Nacional do Meio Ambiente 50% (cinquenta por cento) dos valores arrecadados em pagamento de multas aplicadas pela União, percentual que poderá ser alterado a critério dos órgãos arrecadadores.', array['Incluído pela Lei nº 14.691, de 2023']::text[], 'CAPÍTULO VI – DA INFRAÇÃO ADMINISTRATIVA', 256),
((select id from public.normas where slug = 'lei-9605-1998'), 'art73.p2', 'art73', 'paragrafo', '§ 2º', 'Art. 73', '(VETADO).', array['Incluído pela Lei nº 14.691, de 2023']::text[], 'CAPÍTULO VI – DA INFRAÇÃO ADMINISTRATIVA', 257),
((select id from public.normas where slug = 'lei-9605-1998'), 'art74', null, 'artigo', 'Art. 74', 'Art. 74', 'A multa terá por base a unidade, hectare, metro cúbico, quilograma ou outra medida pertinente, de acordo com o objeto jurídico lesado.', '{}'::text[], 'CAPÍTULO VI – DA INFRAÇÃO ADMINISTRATIVA', 258),
((select id from public.normas where slug = 'lei-9605-1998'), 'art75', null, 'artigo', 'Art. 75', 'Art. 75', 'O valor da multa de que trata este Capítulo será fixado no regulamento desta Lei e corrigido periodicamente, com base nos índices estabelecidos na legislação pertinente, sendo o mínimo de R$ 50,00 (cinqüenta reais) e o máximo de R$ 50.000.000,00 (cinqüenta milhões de reais).', '{}'::text[], 'CAPÍTULO VI – DA INFRAÇÃO ADMINISTRATIVA', 259),
((select id from public.normas where slug = 'lei-9605-1998'), 'art76', null, 'artigo', 'Art. 76', 'Art. 76', 'O pagamento de multa imposta pelos Estados, Municípios, Distrito Federal ou Territórios substitui a multa federal na mesma hipótese de incidência.', '{}'::text[], 'CAPÍTULO VI – DA INFRAÇÃO ADMINISTRATIVA', 260),
((select id from public.normas where slug = 'lei-9605-1998'), 'art77', null, 'artigo', 'Art. 77', 'Art. 77', 'Resguardados a soberania nacional, a ordem pública e os bons costumes, o Governo brasileiro prestará, no que concerne ao meio ambiente, a necessária cooperação a outro país, sem qualquer ônus, quando solicitado para:', '{}'::text[], 'CAPÍTULO VII – DA COOPERAÇÃO INTERNACIONAL PARA A PRESERVAÇÃO DO MEIO AMBIENTE', 261),
((select id from public.normas where slug = 'lei-9605-1998'), 'art77.inc1', 'art77', 'inciso', 'I', 'Art. 77', 'produção de prova;', '{}'::text[], 'CAPÍTULO VII – DA COOPERAÇÃO INTERNACIONAL PARA A PRESERVAÇÃO DO MEIO AMBIENTE', 262),
((select id from public.normas where slug = 'lei-9605-1998'), 'art77.inc2', 'art77', 'inciso', 'II', 'Art. 77', 'exame de objetos e lugares;', '{}'::text[], 'CAPÍTULO VII – DA COOPERAÇÃO INTERNACIONAL PARA A PRESERVAÇÃO DO MEIO AMBIENTE', 263),
((select id from public.normas where slug = 'lei-9605-1998'), 'art77.inc3', 'art77', 'inciso', 'III', 'Art. 77', 'informações sobre pessoas e coisas;', '{}'::text[], 'CAPÍTULO VII – DA COOPERAÇÃO INTERNACIONAL PARA A PRESERVAÇÃO DO MEIO AMBIENTE', 264),
((select id from public.normas where slug = 'lei-9605-1998'), 'art77.inc4', 'art77', 'inciso', 'IV', 'Art. 77', 'presença temporária da pessoa presa, cujas declarações tenham relevância para a decisão de uma causa;', '{}'::text[], 'CAPÍTULO VII – DA COOPERAÇÃO INTERNACIONAL PARA A PRESERVAÇÃO DO MEIO AMBIENTE', 265),
((select id from public.normas where slug = 'lei-9605-1998'), 'art77.inc5', 'art77', 'inciso', 'V', 'Art. 77', 'outras formas de assistência permitidas pela legislação em vigor ou pelos tratados de que o Brasil seja parte.', '{}'::text[], 'CAPÍTULO VII – DA COOPERAÇÃO INTERNACIONAL PARA A PRESERVAÇÃO DO MEIO AMBIENTE', 266),
((select id from public.normas where slug = 'lei-9605-1998'), 'art77.p1', 'art77', 'paragrafo', '§ 1º', 'Art. 77', 'A solicitação de que trata este artigo será dirigida ao Ministério da Justiça, que a remeterá, quando necessário, ao órgão judiciário competente para decidir a seu respeito, ou a encaminhará à autoridade capaz de atendê-la.', '{}'::text[], 'CAPÍTULO VII – DA COOPERAÇÃO INTERNACIONAL PARA A PRESERVAÇÃO DO MEIO AMBIENTE', 267),
((select id from public.normas where slug = 'lei-9605-1998'), 'art77.p2', 'art77', 'paragrafo', '§ 2º', 'Art. 77', 'A solicitação deverá conter:', '{}'::text[], 'CAPÍTULO VII – DA COOPERAÇÃO INTERNACIONAL PARA A PRESERVAÇÃO DO MEIO AMBIENTE', 268),
((select id from public.normas where slug = 'lei-9605-1998'), 'art77.p2.inc1', 'art77.p2', 'inciso', 'I', 'Art. 77', 'o nome e a qualificação da autoridade solicitante;', '{}'::text[], 'CAPÍTULO VII – DA COOPERAÇÃO INTERNACIONAL PARA A PRESERVAÇÃO DO MEIO AMBIENTE', 269),
((select id from public.normas where slug = 'lei-9605-1998'), 'art77.p2.inc2', 'art77.p2', 'inciso', 'II', 'Art. 77', 'o objeto e o motivo de sua formulação;', '{}'::text[], 'CAPÍTULO VII – DA COOPERAÇÃO INTERNACIONAL PARA A PRESERVAÇÃO DO MEIO AMBIENTE', 270),
((select id from public.normas where slug = 'lei-9605-1998'), 'art77.p2.inc3', 'art77.p2', 'inciso', 'III', 'Art. 77', 'a descrição sumária do procedimento em curso no país solicitante;', '{}'::text[], 'CAPÍTULO VII – DA COOPERAÇÃO INTERNACIONAL PARA A PRESERVAÇÃO DO MEIO AMBIENTE', 271),
((select id from public.normas where slug = 'lei-9605-1998'), 'art77.p2.inc4', 'art77.p2', 'inciso', 'IV', 'Art. 77', 'a especificação da assistência solicitada;', '{}'::text[], 'CAPÍTULO VII – DA COOPERAÇÃO INTERNACIONAL PARA A PRESERVAÇÃO DO MEIO AMBIENTE', 272),
((select id from public.normas where slug = 'lei-9605-1998'), 'art77.p2.inc5', 'art77.p2', 'inciso', 'V', 'Art. 77', 'a documentação indispensável ao seu esclarecimento, quando for o caso.', '{}'::text[], 'CAPÍTULO VII – DA COOPERAÇÃO INTERNACIONAL PARA A PRESERVAÇÃO DO MEIO AMBIENTE', 273),
((select id from public.normas where slug = 'lei-9605-1998'), 'art78', null, 'artigo', 'Art. 78', 'Art. 78', 'Para a consecução dos fins visados nesta Lei e especialmente para a reciprocidade da cooperação internacional, deve ser mantido sistema de comunicações apto a facilitar o intercâmbio rápido e seguro de informações com órgãos de outros países.', '{}'::text[], 'CAPÍTULO VII – DA COOPERAÇÃO INTERNACIONAL PARA A PRESERVAÇÃO DO MEIO AMBIENTE', 274),
((select id from public.normas where slug = 'lei-9605-1998'), 'art79', null, 'artigo', 'Art. 79', 'Art. 79', 'Aplicam-se subsidiariamente a esta Lei as disposições do Código Penal e do Código de Processo Penal.', '{}'::text[], 'CAPÍTULO VIII – DISPOSIÇÕES FINAIS', 275),
((select id from public.normas where slug = 'lei-9605-1998'), 'art79a', null, 'artigo', 'Art. 79-A', 'Art. 79-A', 'Para o cumprimento do disposto nesta Lei, os órgãos ambientais integrantes do SISNAMA, responsáveis pela execução de programas e projetos e pelo controle e fiscalização dos estabelecimentos e das atividades suscetíveis de degradarem a qualidade ambiental, ficam autorizados a celebrar, com força de título executivo extrajudicial, termo de compromisso com pessoas físicas ou jurídicas responsáveis pela construção, instalação, ampliação e funcionamento de estabelecimentos e atividades utilizadores de recursos ambientais, considerados efetiva ou potencialmente poluidores.', array['Redação dada pela Medida Provisória nº 2.163-41, de 2001']::text[], 'CAPÍTULO VIII – DISPOSIÇÕES FINAIS', 276),
((select id from public.normas where slug = 'lei-9605-1998'), 'art79a.p1', 'art79a', 'paragrafo', '§ 1º', 'Art. 79-A', 'O termo de compromisso a que se refere este artigo destinar-se-á, exclusivamente, a permitir que as pessoas físicas e jurídicas mencionadas no caput possam promover as necessárias correções de suas atividades, para o atendimento das exigências impostas pelas autoridades ambientais competentes, sendo obrigatório que o respectivo instrumento disponha sobre:', array['Redação dada pela Medida Provisória nº 2.163-41, de 2001']::text[], 'CAPÍTULO VIII – DISPOSIÇÕES FINAIS', 277),
((select id from public.normas where slug = 'lei-9605-1998'), 'art79a.p1.inc1', 'art79a.p1', 'inciso', 'I', 'Art. 79-A', 'o nome, a qualificação e o endereço das partes compromissadas e dos respectivos representantes legais;', array['Redação dada pela Medida Provisória nº 2.163-41, de 2001']::text[], 'CAPÍTULO VIII – DISPOSIÇÕES FINAIS', 278),
((select id from public.normas where slug = 'lei-9605-1998'), 'art79a.p1.inc2', 'art79a.p1', 'inciso', 'II', 'Art. 79-A', 'o prazo de vigência do compromisso, que, em função da complexidade das obrigações nele fixadas, poderá variar entre o mínimo de noventa dias e o máximo de três anos, com possibilidade de prorrogação por igual período;', array['Redação dada pela Medida Provisória nº 2.163-41, de 2001']::text[], 'CAPÍTULO VIII – DISPOSIÇÕES FINAIS', 279),
((select id from public.normas where slug = 'lei-9605-1998'), 'art79a.p1.inc3', 'art79a.p1', 'inciso', 'III', 'Art. 79-A', 'a descrição detalhada de seu objeto, o valor do investimento previsto e o cronograma físico de execução e de implantação das obras e serviços exigidos, com metas trimestrais a serem atingidas;', array['Redação dada pela Medida Provisória nº 2.163-41, de 2001']::text[], 'CAPÍTULO VIII – DISPOSIÇÕES FINAIS', 280),
((select id from public.normas where slug = 'lei-9605-1998'), 'art79a.p1.inc4', 'art79a.p1', 'inciso', 'IV', 'Art. 79-A', 'as multas que podem ser aplicadas à pessoa física ou jurídica compromissada e os casos de rescisão, em decorrência do não-cumprimento das obrigações nele pactuadas;', array['Redação dada pela Medida Provisória nº 2.163-41, de 2001']::text[], 'CAPÍTULO VIII – DISPOSIÇÕES FINAIS', 281),
((select id from public.normas where slug = 'lei-9605-1998'), 'art79a.p1.inc5', 'art79a.p1', 'inciso', 'V', 'Art. 79-A', 'o valor da multa de que trata o inciso IV não poderá ser superior ao valor do investimento previsto;', array['Redação dada pela Medida Provisória nº 2.163-41, de 2001']::text[], 'CAPÍTULO VIII – DISPOSIÇÕES FINAIS', 282),
((select id from public.normas where slug = 'lei-9605-1998'), 'art79a.p1.inc6', 'art79a.p1', 'inciso', 'VI', 'Art. 79-A', 'o foro competente para dirimir litígios entre as partes.', array['Incluído pela Medida Provisória nº 2.163-41, de 2001']::text[], 'CAPÍTULO VIII – DISPOSIÇÕES FINAIS', 283),
((select id from public.normas where slug = 'lei-9605-1998'), 'art79a.p2', 'art79a', 'paragrafo', '§ 2º', 'Art. 79-A', 'No tocante aos empreendimentos em curso até o dia 30 de março de 1998, envolvendo construção, instalação, ampliação e funcionamento de estabelecimentos e atividades utilizadores de recursos ambientais, considerados efetiva ou potencialmente poluidores, a assinatura do termo de compromisso deverá ser requerida pelas pessoas físicas e jurídicas interessadas, até o dia 31 de dezembro de 1998, mediante requerimento escrito protocolizado junto aos órgãos competentes do SISNAMA, devendo ser firmado pelo dirigente máximo do estabelecimento.', array['Redação dada pela Medida Provisória nº 2.163-41, de 2001']::text[], 'CAPÍTULO VIII – DISPOSIÇÕES FINAIS', 284),
((select id from public.normas where slug = 'lei-9605-1998'), 'art79a.p3', 'art79a', 'paragrafo', '§ 3º', 'Art. 79-A', 'Da data da protocolização do requerimento previsto no § 2º e enquanto perdurar a vigência do correspondente termo de compromisso, ficarão suspensas, em relação aos fatos que deram causa à celebração do instrumento, a aplicação de sanções administrativas contra a pessoa física ou jurídica que o houver firmado.', array['Redação dada pela Medida Provisória nº 2.163-41, de 2001']::text[], 'CAPÍTULO VIII – DISPOSIÇÕES FINAIS', 285),
((select id from public.normas where slug = 'lei-9605-1998'), 'art79a.p4', 'art79a', 'paragrafo', '§ 4º', 'Art. 79-A', 'A celebração do termo de compromisso de que trata este artigo não impede a execução de eventuais multas aplicadas antes da protocolização do requerimento.', array['Redação dada pela Medida Provisória nº 2.163-41, de 2001']::text[], 'CAPÍTULO VIII – DISPOSIÇÕES FINAIS', 286),
((select id from public.normas where slug = 'lei-9605-1998'), 'art79a.p5', 'art79a', 'paragrafo', '§ 5º', 'Art. 79-A', 'Considera-se rescindido de pleno direito o termo de compromisso, quando descumprida qualquer de suas cláusulas, ressalvado o caso fortuito ou de força maior.', array['Incluído pela Medida Provisória nº 2.163-41, de 2001']::text[], 'CAPÍTULO VIII – DISPOSIÇÕES FINAIS', 287),
((select id from public.normas where slug = 'lei-9605-1998'), 'art79a.p6', 'art79a', 'paragrafo', '§ 6º', 'Art. 79-A', 'O termo de compromisso deverá ser firmado em até noventa dias, contados da protocolização do requerimento.', array['Incluído pela Medida Provisória nº 2.163-41, de 2001']::text[], 'CAPÍTULO VIII – DISPOSIÇÕES FINAIS', 288),
((select id from public.normas where slug = 'lei-9605-1998'), 'art79a.p7', 'art79a', 'paragrafo', '§ 7º', 'Art. 79-A', 'O requerimento de celebração do termo de compromisso deverá conter as informações necessárias à verificação da sua viabilidade técnica e jurídica, sob pena de indeferimento do plano.', array['Incluído pela Medida Provisória nº 2.163-41, de 2001']::text[], 'CAPÍTULO VIII – DISPOSIÇÕES FINAIS', 289),
((select id from public.normas where slug = 'lei-9605-1998'), 'art79a.p8', 'art79a', 'paragrafo', '§ 8º', 'Art. 79-A', 'Sob pena de ineficácia, os termos de compromisso deverão ser publicados no órgão oficial competente, mediante extrato.', array['Incluído pela Medida Provisória nº 2.163-41, de 2001']::text[], 'CAPÍTULO VIII – DISPOSIÇÕES FINAIS', 290),
((select id from public.normas where slug = 'lei-9605-1998'), 'art80', null, 'artigo', 'Art. 80', 'Art. 80', 'O Poder Executivo regulamentará esta Lei no prazo de noventa dias a contar de sua publicação.', '{}'::text[], 'CAPÍTULO VIII – DISPOSIÇÕES FINAIS', 291),
((select id from public.normas where slug = 'lei-9605-1998'), 'art81', null, 'artigo', 'Art. 81', 'Art. 81', '(VETADO)', '{}'::text[], 'CAPÍTULO VIII – DISPOSIÇÕES FINAIS', 292),
((select id from public.normas where slug = 'lei-9605-1998'), 'art82', null, 'artigo', 'Art. 82', 'Art. 82', 'Revogam-se as disposições em contrário.', '{}'::text[], 'CAPÍTULO VIII – DISPOSIÇÕES FINAIS', 293);

select public.sincronizar_dispositivos((select id from public.normas where slug = 'lei-9605-1998'));
commit;
